# ============================================================
# GLOBAL USER-FACING NUMBER FORMAT
# ============================================================
# Keep database/calculation precision unchanged, but show all floating
# numeric values in tables with a maximum of 2 decimal places.

def _format_df_for_display(data):
    if not isinstance(data, pd.DataFrame):
        return data

    display_df = data.copy()

    # V6.7 standard reporting rule:
    # Every visible dataframe gets an automatic serial-number column.
    # It is display-only and is never stored as an employee/database ID.
    if "S.No" not in display_df.columns and "S.No." not in display_df.columns:
        display_df.insert(0, "S.No", range(1, len(display_df) + 1))

    for col in display_df.columns:
        # Only round real numeric columns. Employee IDs, dates, labels, etc.
        # remain untouched.
        if pd.api.types.is_float_dtype(display_df[col]):
            display_df[col] = display_df[col].round(2)

    return display_df


# Preserve Streamlit's original dataframe renderer.
_original_st_dataframe = st.dataframe


def _st_dataframe_two_decimals(data=None, *args, **kwargs):
    return _original_st_dataframe(
        _format_df_for_display(data),
        *args,
        **kwargs,
    )


# Every st.dataframe() in this application now follows the same 2-decimal rule.
st.dataframe = _st_dataframe_two_decimals

# V6.9: editable grids also show S.No without changing the data returned
# to application logic.
_original_st_data_editor = st.data_editor

def _st_data_editor_with_sno(data=None, *args, **kwargs):
    added_sno = isinstance(data, pd.DataFrame) and "S.No" not in data.columns and "S.No." not in data.columns
    display_data = data
    if isinstance(data, pd.DataFrame):
        display_data = data.copy()
        if added_sno:
            display_data.insert(0, "S.No", range(1, len(display_data) + 1))

            disabled = kwargs.get("disabled", None)
            if disabled is False or disabled is None:
                kwargs["disabled"] = ["S.No"]
            elif isinstance(disabled, (list, tuple, set)):
                disabled_list = list(disabled)
                if "S.No" not in disabled_list:
                    disabled_list = ["S.No"] + disabled_list
                kwargs["disabled"] = disabled_list
            # disabled=True already protects all columns.

    result = _original_st_data_editor(display_data, *args, **kwargs)
    if added_sno and isinstance(result, pd.DataFrame) and "S.No" in result.columns:
        result = result.drop(columns=["S.No"])
    return result

st.data_editor = _st_data_editor_with_sno

