        cur.execute("UPDATE employees SET division='Greater Noida Plant' WHERE division IS NULL OR TRIM(division)=''")
        cur.execute("UPDATE attendance a SET division=e.division FROM employees e WHERE a.employee_id=e.employee_id AND (a.division IS NULL OR TRIM(a.division)='')")

