def init_db():
    with get_conn() as c:
        c.execute("""
        CREATE TABLE IF NOT EXISTS departments(
            department TEXT PRIMARY KEY,
            active TEXT NOT NULL DEFAULT 'Yes'
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS employees(
            employee_id TEXT PRIMARY KEY,
            employee_name TEXT NOT NULL,
            department TEXT NOT NULL,
            designation TEXT NOT NULL,
            employee_type TEXT NOT NULL,
            shift TEXT NOT NULL,
            skill_level TEXT,
            monthly_salary REAL NOT NULL DEFAULT 0,
            ot_rate REAL NOT NULL DEFAULT 0,
            working_days INTEGER NOT NULL DEFAULT 26,
            joining_date TEXT,
            mobile_number TEXT,
            email TEXT,
            status TEXT NOT NULL DEFAULT 'Active',
            remarks TEXT
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS machines(
            machine TEXT PRIMARY KEY,
            department TEXT NOT NULL,
            standard_manpower INTEGER NOT NULL,
            target_ton REAL NOT NULL
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS attendance(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            work_date TEXT NOT NULL,
            shift TEXT NOT NULL,
            employee_id TEXT NOT NULL,
            status TEXT NOT NULL,
            ot_hours REAL NOT NULL DEFAULT 0,
            UNIQUE(work_date, shift, employee_id)
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS manpower_allocation(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            work_date TEXT NOT NULL,
            shift TEXT NOT NULL,
            machine TEXT NOT NULL,
            employee_id TEXT NOT NULL,
            role TEXT NOT NULL,
            UNIQUE(work_date, shift, machine, employee_id)
        )
        """)
        c.execute("""
        CREATE TABLE IF NOT EXISTS production(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            work_date TEXT NOT NULL,
            shift TEXT NOT NULL,
            machine TEXT NOT NULL,
            production_ton REAL NOT NULL DEFAULT 0,
            target_ton REAL NOT NULL DEFAULT 0,
            waste_ton REAL NOT NULL DEFAULT 0,
            breakdown_hours REAL NOT NULL DEFAULT 0,
            paper_cost REAL NOT NULL DEFAULT 0,
            ink_cost REAL NOT NULL DEFAULT 0,
            glue_cost REAL NOT NULL DEFAULT 0,
            other_material_cost REAL NOT NULL DEFAULT 0,
            UNIQUE(work_date, shift, machine)
        )
        """)

        existing_cols = {
            row[1] for row in c.execute("PRAGMA table_info(employees)").fetchall()
        }
        migrations = {
            "skill_level": "TEXT",
            "joining_date": "TEXT",
            "mobile_number": "TEXT",
            "email": "TEXT",
            "status": "TEXT NOT NULL DEFAULT 'Active'",
            "remarks": "TEXT",
        }
        for col, definition in migrations.items():
            if col not in existing_cols:
                c.execute(f"ALTER TABLE employees ADD COLUMN {col} {definition}")

        # V6 CLEAN SLATE: SQLite fallback does not seed Departments or Machines.



def _normalize_postgres_numbers(df):
    """
    Convert PostgreSQL NUMERIC/DECIMAL values returned by psycopg2
    from decimal.Decimal to Python float for reliable Pandas arithmetic.
    Stored PostgreSQL values are not modified.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    for col in df.columns:
        if df[col].dtype == "object":
            if df[col].map(lambda value: isinstance(value, Decimal)).any():
                df[col] = df[col].map(
                    lambda value: float(value)
                    if isinstance(value, Decimal)
                    else value
                )

    return df


def read_df(sql, params=()):
    pg_sql = sql.replace("?", "%s")

    conn = get_pg_conn()

    try:
        cur = conn.cursor()
        cur.execute(pg_sql, params)

        rows = cur.fetchall()
        columns = [desc[0] for desc in cur.description]

        cur.close()

        return _normalize_postgres_numbers(pd.DataFrame(rows, columns=columns))

    finally:
        conn.close()


def upsert(sql, params):
    pg_sql = sql.replace("?", "%s")

    conn = get_pg_conn()

    try:
        cur = conn.cursor()
        cur.execute(pg_sql, params)

        conn.commit()

        cur.close()

    except Exception:
        conn.rollback()
        raise

    finally:
        conn.close()



# ============================================================
# INDIA TIME DISPLAY
# Database timestamps remain unchanged; user-facing timestamps
# are displayed in Asia/Kolkata (IST).
# ============================================================
IST = ZoneInfo("Asia/Kolkata")

def _to_ist_display(value):
    """Convert a DB timestamp (stored/server UTC) to naive IST for display."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return value
    try:
        ts = pd.Timestamp(value)
        if pd.isna(ts):
            return value
        if ts.tzinfo is None:
            ts = ts.tz_localize("UTC")
        else:
            ts = ts.tz_convert("UTC")
        return ts.tz_convert("Asia/Kolkata").tz_localize(None)
    except Exception:
        return value


def hash_user_password(password, salt=None):
    if salt is None:
        salt = secrets.token_hex(16)
    digest = hashlib.pbkdf2_hmac(
        "sha256",
        password.encode("utf-8"),
        salt.encode("utf-8"),
        200_000,
    )
    return f"{salt}${digest.hex()}"


def verify_user_password(password, stored_hash):
    try:
        salt, saved_digest = str(stored_hash).split("$", 1)
    except ValueError:
        return False
    candidate = hash_user_password(password, salt).split("$", 1)[1]
    return hmac.compare_digest(candidate, saved_digest)


def get_app_users():
    df = read_df("""
        SELECT user_id, username, full_name, role, is_active, created_at, last_login
        FROM app_users
        ORDER BY username
    """)
    # Display timestamps in India Standard Time without changing stored DB values.
    for _col in ("created_at", "last_login"):
        if _col in df.columns:
            df[_col] = df[_col].apply(_to_ist_display)
    return df


def create_app_user(username, full_name, password, role="Viewer", is_active=True):
    username = str(username).strip().lower()
    full_name = str(full_name).strip()
    if not username:
        raise ValueError("Username is required.")
    if not full_name:
        raise ValueError("Full name is required.")
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters.")
    upsert(
        """
        INSERT INTO app_users(username, full_name, password_hash, role, is_active)
        VALUES (?, ?, ?, ?, ?)
        """,
        (username, full_name, hash_user_password(password), role, bool(is_active)),
    )


def authenticate_app_user(username, password):
    username = str(username).strip().lower()
    df = read_df(
        """
        SELECT user_id, username, full_name, password_hash, role, is_active
        FROM app_users
        WHERE LOWER(username) = LOWER(?)
        LIMIT 1
        """,
        (username,),
    )
    if df.empty:
        return None
    row = df.iloc[0]
    if not bool(row["is_active"]):
        return None
    if not verify_user_password(password, row["password_hash"]):
        return None
    upsert(
        "UPDATE app_users SET last_login = CURRENT_TIMESTAMP WHERE user_id = ?",
        (int(row["user_id"]),),
    )
    return {
        "user_id": int(row["user_id"]),
        "username": str(row["username"]),
        "full_name": str(row["full_name"]),
        "role": str(row["role"]),
    }


def _session_token_hash(token):
    return hashlib.sha256(str(token).encode("utf-8")).hexdigest()


def create_login_session(user_id):
    # Store only a hash of the browser token in PostgreSQL.
    raw_token = secrets.token_urlsafe(32)
    token_hash = _session_token_hash(raw_token)

    conn = get_pg_conn()
    try:
        cur = conn.cursor()

        # Keep only valid sessions and remove old/expired rows.
        cur.execute(
            "DELETE FROM app_sessions WHERE expires_at <= CURRENT_TIMESTAMP"
        )

        cur.execute(
            """
            INSERT INTO app_sessions(token_hash, user_id, expires_at)
            VALUES (%s, %s, CURRENT_TIMESTAMP + INTERVAL '12 hours')
            """,
            (token_hash, int(user_id)),
        )

        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

    return raw_token


def restore_login_from_token(raw_token):
    if not raw_token:
        return None

    token_hash = _session_token_hash(raw_token)
    df = read_df(
        """
        SELECT
            u.user_id,
            u.username,
            u.full_name,
            u.role,
            u.is_active
        FROM app_sessions s
        JOIN app_users u
            ON u.user_id = s.user_id
        WHERE s.token_hash = ?
          AND s.expires_at > CURRENT_TIMESTAMP
          AND u.is_active = TRUE
        LIMIT 1
        """,
        (token_hash,),
    )

    if df.empty:
        return None

    row = df.iloc[0]

    # Refresh activity time. The 12-hour expiry remains fixed.
    upsert(
        """
        UPDATE app_sessions
        SET last_seen = CURRENT_TIMESTAMP
        WHERE token_hash = ?
        """,
        (token_hash,),
    )

    return {
        "user_id": int(row["user_id"]),
        "username": str(row["username"]),
        "full_name": str(row["full_name"]),
        "role": str(row["role"]),
    }


def destroy_login_session(raw_token):
    if not raw_token:
        return
    try:
        upsert(
            "DELETE FROM app_sessions WHERE token_hash = ?",
            (_session_token_hash(raw_token),),
        )
    except Exception:
        # Logout should still work even if the cleanup query fails.
        pass


def normalize_text(value, default=""):
    if pd.isna(value):
        return default
    return str(value).strip()


def normalize_number(value, default=0.0):
    if pd.isna(value) or value == "":
        return default
    return float(value)


def normalize_int(value, default=26):
    if pd.isna(value) or value == "":
        return default
    return int(float(value))


def normalize_date(value):
    if pd.isna(value) or value == "":
        return None
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return None
    return parsed.date().isoformat()


def import_employee_excel(uploaded_file):
    try:
        excel = pd.ExcelFile(
            uploaded_file,
            engine="openpyxl"
        )
    
        sheet = (
            "Employee_Data"
            if "Employee_Data" in excel.sheet_names
            else excel.sheet_names[0]
        )

        df = pd.read_excel(
            uploaded_file,
            sheet_name=sheet,
            header=2,
            engine="openpyxl"
        )

    except Exception as exc:
        raise ValueError(
            f"Unable to read Excel file: {exc}"
        ) from exc

    required = [
        "Employee ID",
        "Employee Name",
        "Department",
        "Designation",
        "Employee Type",
        "Shift",
        "Monthly Salary",
    ]
    missing = [c for c in required if c not in df.columns]
    if missing:
        raise ValueError("Missing required columns: " + ", ".join(missing))

    df = df.dropna(how="all").copy()
    if df.empty:
        raise ValueError("No employee rows were found.")

    imported = 0
    updated = 0
    skipped = 0
    errors = []

    existing_ids = set(read_df("SELECT employee_id FROM employees")["employee_id"].astype(str))

    with get_pg_conn() as c:
        cur = c.cursor()
        for idx, row in df.iterrows():
            excel_row = idx + 4
            emp_id = normalize_text(row.get("Employee ID"))
            name = normalize_text(row.get("Employee Name"))
            department = normalize_text(row.get("Department"))
            designation = normalize_text(row.get("Designation"))

            if not emp_id and not name:
                skipped += 1
                continue

            if not emp_id or not name or not department or not designation:
                errors.append(f"Row {excel_row}: Employee ID, name, department and designation are required.")
                continue

            employee_type = normalize_text(row.get("Employee Type"), "Permanent")
            shift = normalize_text(row.get("Shift"), "General")
            skill = normalize_text(row.get("Skill Level"), "")
            monthly_salary = normalize_number(row.get("Monthly Salary"), 0)
            working_days = normalize_int(row.get("Legacy Working Days / Month"), 26)
            ot_rate = normalize_number(row.get("OT Rate / Hour"), 0)
            joining_date = normalize_date(row.get("Joining Date"))
            mobile = normalize_text(row.get("Mobile Number"), "")
            email = normalize_text(row.get("Email"), "")
            status = normalize_text(row.get("Status"), "Active")
            remarks = normalize_text(row.get("Remarks"), "")

            if working_days <= 0:
                errors.append(f"Row {excel_row}: Working days must be greater than zero.")
                continue
            if monthly_salary < 0 or ot_rate < 0:
                errors.append(f"Row {excel_row}: Salary and OT rate cannot be negative.")
                continue

            was_existing = emp_id in existing_ids

            cur.execute("""
                INSERT INTO employees(
                    employee_id, employee_name, department, designation,
                    employee_type, shift, skill_level, monthly_salary,
                    ot_rate, working_days, joining_date, mobile_number,
                    email, status, remarks
                ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
                ON CONFLICT(employee_id) DO UPDATE SET
                    employee_name=excluded.employee_name,
                    department=excluded.department,
                    designation=excluded.designation,
                    employee_type=excluded.employee_type,
                    shift=excluded.shift,
                    skill_level=excluded.skill_level,
                    monthly_salary=excluded.monthly_salary,
                    ot_rate=excluded.ot_rate,
                    working_days=excluded.working_days,
                    joining_date=excluded.joining_date,
                    mobile_number=excluded.mobile_number,
                    email=excluded.email,
                    status=excluded.status,
                    remarks=excluded.remarks
            """, (
                emp_id, name, department, designation, employee_type, shift,
                skill, monthly_salary, ot_rate, working_days, joining_date,
                mobile, email, status, remarks
            ))

            cur.execute("""
                INSERT INTO departments(department, active) VALUES (%s, 'Yes')
                ON CONFLICT(department) DO NOTHING
            """, (department,))

            if was_existing:
                updated += 1
            else:
                imported += 1
                existing_ids.add(emp_id)

    c.commit()
    cur.close()

    return {
        "total_rows": len(df),
        "imported": imported,
        "updated": updated,
        "skipped": skipped,
        "errors": errors,
    }



