@st.cache_data(ttl=60, show_spinner=False)
def get_setting_value(key, default=None):
    df = read_df("SELECT setting_value FROM app_settings WHERE setting_key = ? LIMIT 1", (key,))
    if df.empty:
        return default
    return df.iloc[0]["setting_value"]


def get_setting_float(key, default=0.0):
    try:
        return float(get_setting_value(key, default))
    except (TypeError, ValueError):
        return float(default)


def save_setting_value(key, value):
    upsert(
        """
        INSERT INTO app_settings(setting_key, setting_value)
        VALUES (?, ?)
        ON CONFLICT(setting_key) DO UPDATE SET setting_value = excluded.setting_value
        """,
        (str(key), str(value)),
    )
    get_setting_value.clear()


def can_view_salary(role):
    return str(role) in {"Owner", "Admin", "HR", "Manager"}


def get_effective_permissions(user_id, role):
    role = str(role or "Viewer")
    if role in FULL_CONTROL_ROLES:
        return PAGE_ORDER.copy()
    df = read_df(
        "SELECT page_name, can_access FROM app_user_permissions WHERE user_id = ?",
        (int(user_id),),
    )
    if df.empty:
        return ROLE_DEFAULTS.get(role, ROLE_DEFAULTS["Viewer"]).copy()
    allowed = set(
        df.loc[df["can_access"].astype(bool), "page_name"].astype(str).tolist()
    )
    pages = [page for page in PAGE_ORDER if page in allowed]
    return pages or ["Dashboard"]


def save_user_permissions(user_id, pages):
    pages = set(pages)
    conn = get_pg_conn()
    try:
        cur = conn.cursor()
        cur.execute("DELETE FROM app_user_permissions WHERE user_id = %s", (int(user_id),))
        for page_name in PAGE_ORDER:
            cur.execute(
                """
                INSERT INTO app_user_permissions(user_id, page_name, can_access)
                VALUES (%s, %s, %s)
                """,
                (int(user_id), page_name, page_name in pages),
            )
        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def role_default_permissions(role):
    return ROLE_DEFAULTS.get(str(role), ROLE_DEFAULTS["Viewer"]).copy()



