DIVISIONS = [
    "Greater Noida Plant",
    "Dhaulana Glass Plant",
    "D-63 Head Office",
]
ALL_DIVISIONS = "All Divisions"

def _normalize_master_division(value, fallback=""):
    """Normalize legacy division labels across ALL master imports."""
    raw = _clean_text(value)
    if not raw:
        return fallback
    compact = "".join(ch for ch in raw.upper() if ch.isalnum())

    if compact in {
        "D2SEC63HEADOFFICE","D2SEC63","D63HEADOFFICE","D63",
        "HOD2","D2NOIDA","HEADOFFICE","D2HEADOFFICE"
    }:
        return "D-63 Head Office"
    if "DHAULANA" in compact:
        return "Dhaulana Glass Plant"
    if compact in {"GNOIDA","GNP","NOIDAPLANT"} or "GREATERNOIDA" in compact:
        return "Greater Noida Plant"
    if raw in DIVISIONS:
        return raw
    return fallback or raw


def _department_mapping_dict():
    try:
        df = read_df(
            """SELECT source_department,target_department
               FROM department_mappings WHERE active=TRUE"""
        )
        if df.empty:
            return {}
        return {
            str(r["source_department"]).strip().casefold(): str(r["target_department"]).strip()
            for _, r in df.iterrows()
        }
    except Exception:
        return {}


def _normalize_department_value(value, mapping=None):
    raw = _clean_text(value)
    if not raw:
        return raw
    mapping = mapping if mapping is not None else _department_mapping_dict()
    return mapping.get(raw.casefold(), raw)


