def can_edit_hr(role):
    return str(role) in {"Owner", "Admin", "HR"}


def _clean_code(value):
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except Exception:
        pass
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    text = str(value).strip()
    if text.endswith(".0"):
        try:
            return str(int(float(text)))
        except Exception:
            pass
    return text


def _clean_text(value, default=""):
    if value is None:
        return default
    try:
        if pd.isna(value):
            return default
    except Exception:
        pass
    return str(value).strip()


def _num(value, default=0.0):
    try:
        if value is None or value == "" or pd.isna(value):
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _date_iso(value):
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        return None
    return parsed.date().isoformat()


def _time_text(value):
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, datetime):
        value = value.time()
    if isinstance(value, time):
        return value.strftime("%H:%M")
    if isinstance(value, (int, float)):
        fraction = float(value) % 1
        minutes = int(round(fraction * 24 * 60)) % 1440
        return f"{minutes // 60:02d}:{minutes % 60:02d}"
    raw = str(value).strip()
    for fmt in ("%H:%M:%S", "%H:%M", "%I:%M %p"):
        try:
            return datetime.strptime(raw, fmt).strftime("%H:%M")
        except Exception:
            pass
    return raw or None



def _attendance_col_key(value):
    """Normalize Excel/CSV headers: Employee_ID, Employee ID, Employee Code -> comparable keys."""
    raw = _clean_text(value).lower()
    return "".join(ch for ch in raw if ch.isalnum())


def _attendance_date_iso(value):
    """Attendance files commonly use DD/MM/YYYY; preserve ISO dates as well."""
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()

    raw = str(value).strip()
    if not raw:
        return None

    # Company's standard display/export is DD/MM/YYYY.
    if "/" in raw or ("-" in raw and len(raw.split("-")[0]) <= 2):
        parsed = pd.to_datetime(raw, errors="coerce", dayfirst=True)
    else:
        parsed = pd.to_datetime(raw, errors="coerce")
    if pd.isna(parsed):
        return None
    return parsed.date().isoformat()


def _normalize_attendance_division(value, fallback=None):
    raw = _clean_text(value).upper()
    compact = "".join(ch for ch in raw if ch.isalnum())

    if not compact:
        return fallback

    # Legacy D-2 Sec 63 / D2-NOIDA / D-63 / Head Office aliases.
    if (
        "D2NOIDA" in compact
        or "D2SEC63" in compact
        or "D63" in compact
        or "HEADOFFICE" in compact
        or compact in {"D2", "D2HO"}
    ):
        return "D-63 Head Office"

    if "DHAULANA" in compact:
        return "Dhaulana Glass Plant"

    if "GREATERNOIDA" in compact or compact in {"GNOIDA", "GNP", "NOIDAPLANT"}:
        return "Greater Noida Plant"

    if raw in DIVISIONS:
        return raw

    return fallback


ATTENDANCE_COLUMN_ALIASES = {
    "division": {"division","location","plant"},
    "date": {"date","datein","workdate","attendancedate"},
    "employee_id": {"employeeid","employeecode","paycode","ecode","empcode"},
    "employee_name": {"employeename","name","nameofemployee"},
    "designation": {"designation"},
    "shift": {"shift","shiftcode"},
    "time_in": {"timein","intime"},
    "time_out": {"timeout","outtime"},
    "working_hours": {"workinghours","workinghrs","workhours","actual"},
    "status": {"status","attendancestatus"},
    "remark": {"remark","remarks","hrremark"},
    "day": {"day","dayname"},
}


def _attendance_column_map(columns):
    normalized = {_attendance_col_key(c): c for c in columns}
    mapped = {}
    for target, aliases in ATTENDANCE_COLUMN_ALIASES.items():
        for alias in aliases:
            if alias in normalized:
                mapped[target] = normalized[alias]
                break
    return mapped


def _read_standard_attendance_upload(uploaded_file):
    """Read standard attendance exports without changing the source portal.

    Supports CSV, XLSX and legacy XLS. BTS attendance exports may be a real
    Excel .xls file or an HTML table saved with an .xls extension; both are
    handled here as read-only uploads into Reliable HRMS.
    """
    filename = _clean_text(getattr(uploaded_file, "name", "")).lower()

    def _clean_candidate(table):
        if table is None or table.empty:
            return table
        table = table.copy()
        if isinstance(table.columns, pd.MultiIndex):
            table.columns = [
                _clean_text(" ".join(str(x) for x in col if _clean_text(x)))
                for col in table.columns
            ]
        else:
            table.columns = [_clean_text(c) for c in table.columns]

        mapped = _attendance_column_map(table.columns)
        if mapped.get("employee_id") and mapped.get("date"):
            return table

        # Some report exports place company/report headings above the true header.
        for idx in range(min(35, len(table))):
            row_values = [_clean_text(v) for v in table.iloc[idx].tolist()]
            keys = {_attendance_col_key(v) for v in row_values if v}
            has_emp = bool(keys & ATTENDANCE_COLUMN_ALIASES["employee_id"])
            has_date = bool(keys & ATTENDANCE_COLUMN_ALIASES["date"])
            if has_emp and has_date:
                promoted = table.iloc[idx + 1:].copy()
                promoted.columns = row_values
                promoted.columns = [_clean_text(c) for c in promoted.columns]
                return promoted
        return table

    uploaded_file.seek(0)
    if filename.endswith(".csv"):
        df = pd.read_csv(uploaded_file, dtype=str, keep_default_na=False)
        return _clean_candidate(df)

    if filename.endswith(".xls"):
        raw_bytes = uploaded_file.read()
        if not raw_bytes:
            raise ValueError("The XLS attendance file is empty.")
        probe = raw_bytes[:50000].lstrip().lower()
        html_like = probe.startswith(b"<") or b"<table" in probe or b"<html" in probe

        if html_like:
            try:
                tables = pd.read_html(BytesIO(raw_bytes), header=0)
            except Exception as exc:
                raise ValueError(
                    "Unable to read the BTS XLS/HTML attendance export. "
                    f"Please download the report again: {exc}"
                ) from exc
            candidates = [_clean_candidate(t) for t in tables if t is not None and not t.empty]
            valid = [
                t for t in candidates
                if t is not None
                and _attendance_column_map(t.columns).get("employee_id")
                and _attendance_column_map(t.columns).get("date")
            ]
            if valid:
                return max(valid, key=len)
            if candidates:
                return max(candidates, key=len)
            raise ValueError("No attendance table was found in the BTS XLS export.")

        # Genuine legacy binary .xls workbook.
        try:
            uploaded_file.seek(0)
            raw = pd.read_excel(uploaded_file, header=None, engine="xlrd")
        except Exception as exc:
            raise ValueError(
                "Unable to read the legacy XLS attendance file. "
                f"Please download it again from BTS: {exc}"
            ) from exc

        header_idx = 0
        found = False
        for idx in range(min(35, len(raw))):
            keys = {_attendance_col_key(v) for v in raw.iloc[idx].tolist() if _clean_text(v)}
            if bool(keys & ATTENDANCE_COLUMN_ALIASES["employee_id"]) and bool(keys & ATTENDANCE_COLUMN_ALIASES["date"]):
                header_idx = idx
                found = True
                break
        uploaded_file.seek(0)
        df = pd.read_excel(uploaded_file, header=header_idx, engine="xlrd")
        df.columns = [_clean_text(c) for c in df.columns]
        return df

    # XLSX: find a header row that contains Employee_ID / Employee Code / PayCode.
    uploaded_file.seek(0)
    raw = pd.read_excel(uploaded_file, header=None, engine="openpyxl")
    header_idx = 0
    found = False
    for idx in range(min(35, len(raw))):
        keys = {_attendance_col_key(v) for v in raw.iloc[idx].tolist() if _clean_text(v)}
        has_emp = bool(keys & ATTENDANCE_COLUMN_ALIASES["employee_id"])
        has_date = bool(keys & ATTENDANCE_COLUMN_ALIASES["date"])
        if has_emp and has_date:
            header_idx = idx
            found = True
            break

    uploaded_file.seek(0)
    df = pd.read_excel(uploaded_file, header=header_idx, engine="openpyxl")
    df.columns = [_clean_text(c) for c in df.columns]
    return df

def detect_standard_attendance_file_division(uploaded_file, fallback=None):
    original_position = 0
    try:
        original_position = uploaded_file.tell()
    except Exception:
        pass
    try:
        df = _read_standard_attendance_upload(uploaded_file)
        cmap = _attendance_column_map(df.columns)
        div_col = cmap.get("division")
        if not div_col:
            return fallback
        detected = {
            _normalize_attendance_division(v)
            for v in df[div_col].head(100).tolist()
            if _normalize_attendance_division(v)
        }
        if len(detected) == 1:
            return next(iter(detected))
        return fallback
    finally:
        _restore_upload_position(uploaded_file, original_position)


def _validate_and_enrich_attendance_records(records):
    """Validate attendance without blocking good rows.

    Matched employees are enriched from Employee Master. Unknown Employee IDs and
    division mismatches are retained as attendance transactions but forced to
    HR Review. Employee Master is never created/changed during import.
    """
    if not records:
        return records

    master = read_df(
        """SELECT employee_id,employee_name,division,department,designation,shift,status
           FROM employees"""
    )
    master_map = {}
    if not master.empty:
        master["employee_id"] = master["employee_id"].astype(str)
        master_map = {str(r["employee_id"]): r.to_dict() for _, r in master.iterrows()}

    for rec in records:
        emp_id = str(rec.get("employee_id", "")).strip()
        rec["source_employee_name"] = _clean_text(rec.get("employee_name")) or emp_id
        emp = master_map.get(emp_id)
        issue = ""
        emp_status = _clean_text(emp.get("status")).upper() if emp else ""
        inactive_master = bool(emp) and emp_status in {"INACTIVE", "LEFT", "RESIGNED", "TERMINATED"}
        pending_master = (
            bool(emp)
            and not inactive_master
            and _clean_text(emp.get("department")).upper() == "HR REVIEW"
        )
        if not emp:
            issue = "Employee ID not found in Employee Master"
        elif inactive_master:
            rec["skip_import"] = True
            rec["source_issue"] = "Inactive Employee in Master"
            rec["review_required"] = False
            rec["status"] = "Inactive"
            rec["ot_hours"] = 0.0
            continue
        elif pending_master:
            issue = "Employee ID awaiting HR Master confirmation"
        else:
            master_div = _clean_text(emp.get("division"))
            rec_div = _clean_text(rec.get("division"))
            if master_div and rec_div and master_div != rec_div:
                issue = f"Division mismatch: master={master_div}; file={rec_div}"
            else:
                rec["employee_name"] = _clean_text(emp.get("employee_name")) or rec.get("employee_name") or emp_id
                rec["designation"] = _clean_text(emp.get("designation")) or rec.get("designation", "")
                if not _clean_text(rec.get("shift")):
                    rec["shift"] = _clean_text(emp.get("shift")) or "General"

        rec["source_issue"] = issue
        if issue:
            rec["status"] = "HR Review"
            rec["review_required"] = True
            existing_remark = _clean_text(rec.get("remark"))
            if issue not in existing_remark:
                rec["remark"] = f"{existing_remark} | {issue}".strip(" |")
            rec["ot_hours"] = 0.0

    return records

def _hours_value(value):
    if value is None:
        return 0.0
    try:
        if pd.isna(value):
            return 0.0
    except Exception:
        pass
    if isinstance(value, timedelta):
        return value.total_seconds() / 3600.0
    if isinstance(value, datetime):
        value = value.time()
    if isinstance(value, time):
        return value.hour + value.minute / 60.0 + value.second / 3600.0
    if isinstance(value, (int, float)):
        raw = float(value)
        return raw * 24.0 if 0 <= raw < 1.5 else raw
    raw = str(value).strip()
    if not raw:
        return 0.0
    try:
        parts = [float(x) for x in raw.split(":")]
        return parts[0] + (parts[1] if len(parts) > 1 else 0) / 60.0 + (parts[2] if len(parts) > 2 else 0) / 3600.0
    except Exception:
        return _num(value, 0.0)


def _time_difference_hours(time_in_value, time_out_value):
    time_in_text = _time_text(time_in_value)
    time_out_text = _time_text(time_out_value)
    if not time_in_text or not time_out_text:
        return 0.0
    try:
        in_h, in_m = [int(x) for x in time_in_text.split(":")[:2]]
        out_h, out_m = [int(x) for x in time_out_text.split(":")[:2]]
    except Exception:
        return 0.0
    in_minutes = in_h * 60 + in_m
    out_minutes = out_h * 60 + out_m
    return ((out_minutes - in_minutes) % 1440) / 60.0


def _map_attendance_status(raw_status, working_hours=0.0, time_in_value=None, time_out_value=None, day_name=""):
    raw = _clean_text(raw_status).upper().replace(" ", "")
    mapping = {
        "PP": "Present", "P": "Present", "PRESENT": "Present",
        "AA": "Absent", "A": "Absent", "ABSENT": "Absent",
        "WO": "WO", "W/O": "WO", "OFF": "WO",
        "H": "Holiday", "PH": "Holiday", "HOLIDAY": "Holiday", "PUBLICHOLIDAY": "Holiday",
        "HD": "Half Day", "HALFDAY": "Half Day",
        "CL": "CL", "SL": "SL", "EL": "EL", "LWP": "LWP",
        "LEAVE": "Leave", "PA": "HR Review", "AP": "HR Review",
    }
    tin = _time_text(time_in_value)
    tout = _time_text(time_out_value)
    has_in = bool(tin and tin != "00:00")
    has_out = bool(tout and tout != "00:00")
    # Biometric PP/P/PRESENT is not final Present unless both punches exist.
    # Missing In or Out punch must be confirmed by HR.
    if raw in {"PP", "P", "PRESENT"} and not (has_in and has_out):
        return "HR Review"
    if raw in mapping:
        return mapping[raw]
    if has_in and has_out:
        return "Present"
    if has_in != has_out:
        return "HR Review"
    if _clean_text(day_name).upper().startswith("SUN"):
        return "WO"
    return "Absent"


def _infer_shift(time_in_value, division, time_out_value=None):
    if division != "Greater Noida Plant":
        return "General"
    t = _time_text(time_in_value)
    if not t or t == "00:00":
        t = _time_text(time_out_value)
    if not t or t == "00:00":
        return "General"
    try:
        hour = int(t.split(":")[0])
    except Exception:
        return "General"
    return "A" if 5 <= hour < 16 else "B"


def _calendar_days_for(value):
    parsed = pd.to_datetime(value, errors="coerce")
    if pd.isna(parsed):
        parsed = pd.Timestamp(date.today())
    return monthrange(int(parsed.year), int(parsed.month))[1]


def _month_key(month_value):
    parsed = pd.to_datetime(month_value)
    return parsed.strftime("%Y-%m")


def _month_range(month_value):
    parsed = pd.to_datetime(month_value)
    first = date(int(parsed.year), int(parsed.month), 1)
    last = date(int(parsed.year), int(parsed.month), monthrange(int(parsed.year), int(parsed.month))[1])
    return first, last


def _bulk_upsert_employees_from_attendance(records):
    if not records:
        return
    unique = {}
    for rec in records:
        emp_id = str(rec.get("employee_id", "")).strip()
        if not emp_id:
            continue
        unique[emp_id] = rec
    conn = get_pg_conn()
    try:
        cur = conn.cursor()
        rows = []
        for emp_id, rec in unique.items():
            rows.append((
                emp_id,
                rec.get("employee_name") or emp_id,
                rec.get("division") or "Greater Noida Plant",
                rec.get("designation") or "Employee",
                rec.get("shift") if rec.get("shift") in ("A", "B") else "General",
            ))
        cur.executemany("""
            INSERT INTO employees(employee_id, employee_name, department, designation, employee_type, shift, division, status)
            VALUES (%s, %s, 'General', %s, 'Permanent', %s, %s, 'Active')
            ON CONFLICT(employee_id) DO UPDATE SET
                employee_name = CASE WHEN excluded.employee_name <> '' THEN excluded.employee_name ELSE employees.employee_name END,
                designation = CASE WHEN excluded.designation NOT IN ('', 'Employee') THEN excluded.designation ELSE employees.designation END,
                division = excluded.division
        """, [(r[0], r[1], r[3], r[4], r[2]) for r in rows])
        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def _bulk_upsert_attendance(records, source_type, replace_scope=False):
    if not records:
        return 0
    records = _validate_and_enrich_attendance_records(records)
    # Employees already marked inactive/left/resigned/terminated in Employee Master
    # must not be recreated, imported, or sent to HR Review from a biometric file.
    records = [rec for rec in records if not bool(rec.get("skip_import", False))]
    if not records:
        return 0

    # FK-HR-REVIEW-PLACEHOLDER-V1
    # attendance.employee_id references employees.employee_id. Unknown biometric
    # employees therefore need a temporary master reference before their rows can
    # be stored for HR Review. Existing master records are never overwritten here.
    unknown_records = [
        rec for rec in records
        if _clean_text(rec.get("source_issue")) == "Employee ID not found in Employee Master"
    ]
    if unknown_records:
        conn_master = get_pg_conn()
        try:
            cur_master = conn_master.cursor()
            for rec in unknown_records:
                emp_id = str(rec.get("employee_id", "")).strip()
                if not emp_id:
                    continue
                emp_name = _clean_text(rec.get("source_employee_name")) or _clean_text(rec.get("employee_name")) or emp_id
                designation = _clean_text(rec.get("designation")) or "Employee"
                division = _clean_text(rec.get("division")) or "Greater Noida Plant"
                shift = _clean_text(rec.get("shift"))
                if shift not in ("A", "B"):
                    shift = "General"
                cur_master.execute(
                    """INSERT INTO employees(
                           employee_id,employee_name,department,designation,
                           employee_type,shift,division,status
                       ) VALUES (%s,%s,'HR Review',%s,'Permanent',%s,%s,'Active')
                       ON CONFLICT(employee_id) DO NOTHING""",
                    (emp_id, emp_name, designation, shift, division)
                )
            conn_master.commit()
            cur_master.close()
        except Exception:
            conn_master.rollback()
            raise
        finally:
            conn_master.close()

    conn = get_pg_conn()
    try:
        cur = conn.cursor()

        # BTS FULL-REFRESH MODE
        # When enabled, this validated upload becomes the attendance source of truth
        # for every division/date present in the parsed records. Deletion and insert
        # happen in the SAME transaction, so a failed insert rolls the delete back.
        if replace_scope:
            scope = {}
            for rec in records:
                div = _clean_text(rec.get("division"))
                work_date = _clean_text(rec.get("work_date"))
                if div and work_date:
                    scope.setdefault(div, set()).add(work_date)
            for div, dates in scope.items():
                cur.execute(
                    "DELETE FROM attendance WHERE division=%s AND work_date = ANY(%s::date[])",
                    (div, sorted(dates))
                )

        payload = []
        for rec in records:
            payload.append((
                rec["work_date"], rec["shift"], rec["employee_id"], rec["status"], float(rec.get("ot_hours", 0)),
                rec["division"], rec.get("designation", ""), rec.get("day_name", ""), rec.get("time_in"), rec.get("time_out"),
                float(rec.get("working_hours", 0)), rec.get("raw_status", ""), rec.get("remark", ""), source_type,
                bool(rec.get("review_required", False)), rec.get("source_employee_name", rec.get("employee_name", "")),
                rec.get("source_issue", ""),
            ))
        execute_values(cur, """
            INSERT INTO attendance(
                work_date, shift, employee_id, status, ot_hours, division, designation,
                day_name, time_in, time_out, working_hours, raw_status, remark,
                source_type, review_required, source_employee_name, source_issue
            ) VALUES %s
            ON CONFLICT(work_date, shift, employee_id) DO UPDATE SET
                status=excluded.status, ot_hours=excluded.ot_hours, division=excluded.division,
                designation=excluded.designation, day_name=excluded.day_name,
                time_in=excluded.time_in, time_out=excluded.time_out,
                working_hours=excluded.working_hours, raw_status=excluded.raw_status,
                remark=CASE WHEN COALESCE(attendance.remark,'') <> '' AND COALESCE(excluded.remark,'') = '' THEN attendance.remark ELSE excluded.remark END,
                source_type=excluded.source_type, review_required=excluded.review_required,
                source_employee_name=excluded.source_employee_name, source_issue=excluded.source_issue,
                updated_at=CURRENT_TIMESTAMP
        """, payload, page_size=1000)
        conn.commit(); cur.close(); return len(payload)
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()



