def _restore_upload_position(uploaded_file, position=0):
    try:
        uploaded_file.seek(position)
    except Exception:
        try:
            uploaded_file.seek(0)
        except Exception:
            pass


def detect_salary_workbook_division(uploaded_file):
    filename = _clean_text(getattr(uploaded_file, "name", "")).lower()
    if "dhaulana" in filename:
        return "Dhaulana Glass Plant"
    if "head office" in filename or "head-office" in filename or "d-63" in filename or "d63" in filename:
        return "D-63 Head Office"
    if "greater noida" in filename:
        return "Greater Noida Plant"

    original_position = 0
    try:
        original_position = uploaded_file.tell()
    except Exception:
        pass

    try:
        uploaded_file.seek(0)
        wb = load_workbook(uploaded_file, data_only=True, read_only=True)
        sheet_names = [str(s).strip() for s in wb.sheetnames]
        joined_names = " | ".join(sheet_names).lower()

        if "dhaulana" in joined_names:
            return "Dhaulana Glass Plant"
        if "head-office" in joined_names or "head office" in joined_names or "d-63" in joined_names or "d63" in joined_names:
            return "D-63 Head Office"

        ws = wb[sheet_names[0]]
        scan_values = []
        for row in ws.iter_rows(min_row=1, max_row=min(12, ws.max_row), values_only=True):
            scan_values.extend([_clean_text(v) for v in row if _clean_text(v)])
        scan_upper = " | ".join(scan_values).upper()

        if "DHAULANA" in scan_upper:
            return "Dhaulana Glass Plant"
        if "HEAD-OFFICE" in scan_upper or "HEAD OFFICE" in scan_upper:
            return "D-63 Head Office"
        if "E-CODE" in scan_upper and "SALARY RATE" in scan_upper and "ADDITIONAL ALLOWANCE" in scan_upper:
            return "Dhaulana Glass Plant"
        if "E-CODE" in scan_upper and "REVISED SALARY RATE" in scan_upper:
            if any("head" in s.lower() for s in sheet_names):
                return "D-63 Head Office"
            return "Greater Noida Plant"
    finally:
        _restore_upload_position(uploaded_file, original_position)

    return None


def detect_attendance_workbook_division(uploaded_file):
    filename = _clean_text(getattr(uploaded_file, "name", "")).lower()
    if "dhaulana" in filename:
        return "Dhaulana Glass Plant"
    if "head office" in filename or "head-office" in filename or "d-63" in filename or "d63" in filename:
        return "D-63 Head Office"
    if "greater noida" in filename:
        return "Greater Noida Plant"

    original_position = 0
    try:
        original_position = uploaded_file.tell()
    except Exception:
        pass

    try:
        uploaded_file.seek(0)
        wb = load_workbook(uploaded_file, data_only=True, read_only=True)
        sheet_names = [str(s).strip() for s in wb.sheetnames]
        joined_names = " | ".join(sheet_names).lower()

        if "dhaulana" in joined_names:
            return "Dhaulana Glass Plant"

        ws = wb[sheet_names[0]]

        marker_values = set()
        for r in range(1, min(16, ws.max_row) + 1):
            marker_values.add(_clean_text(ws.cell(r, 3).value).lower().replace(" ", "_"))
        if "in_time" in marker_values and "out_time" in marker_values:
            return "Dhaulana Glass Plant"

        header_values = []
        for r in range(1, min(20, ws.max_row) + 1):
            row_values = [_clean_text(ws.cell(r, c).value) for c in range(1, min(20, ws.max_column) + 1)]
            upper = [v.upper() for v in row_values if v]
            if "EMPLOYEE CODE" in upper or ("PAYCODE" in upper and "EMPLOYEE NAME" in upper):
                header_values = upper
                break

        if header_values:
            if "SHIFT CODE" in header_values:
                return "D-63 Head Office"
            return "Greater Noida Plant"
    finally:
        _restore_upload_position(uploaded_file, original_position)

    return None

def import_standard_attendance_excel(uploaded_file, division, target_date=None, dry_run=False, start_date=None, end_date=None, replace_scope=False):
    """
    Accepts Reliable Packaging standard CSV/XLSX as well as the older Employee Code/PayCode exports.

    Standard headers:
    Division, Date, Employee_ID, Employee_Name, Designation, Shift,
    Time_In, Time_Out, Working_Hours, Status, Remark
    """
    df = _read_standard_attendance_upload(uploaded_file)
    cmap = _attendance_column_map(df.columns)

    required = ["date", "employee_id"]
    missing_required = [x for x in required if x not in cmap]
    if missing_required:
        raise ValueError(
            "Attendance file columns are not recognized. Required: Date and Employee_ID. "
            "Recommended standard columns: Division, Date, Employee_ID, Employee_Name, "
            "Designation, Shift, Time_In, Time_Out, Working_Hours, Status, Remark."
        )

    records = []
    detected_divisions = set()

    for _, row in df.iterrows():
        emp_id = _clean_code(row.get(cmap["employee_id"]))
        if not emp_id:
            continue

        work_date = _attendance_date_iso(row.get(cmap["date"]))
        if not work_date:
            continue
        if target_date is not None and work_date != target_date.isoformat():
            continue
        if start_date is not None and work_date < start_date.isoformat():
            continue
        if end_date is not None and work_date > end_date.isoformat():
            continue

        row_div_raw = row.get(cmap["division"]) if "division" in cmap else ""
        row_div = _normalize_attendance_division(row_div_raw, fallback=division)
        if not row_div:
            row_div = division
        detected_divisions.add(row_div)

        parsed_date = pd.to_datetime(work_date)
        day_value = row.get(cmap["day"]) if "day" in cmap else ""
        day_name = _clean_text(day_value) or parsed_date.strftime("%a")

        time_in_value = row.get(cmap["time_in"]) if "time_in" in cmap else None
        time_out_value = row.get(cmap["time_out"]) if "time_out" in cmap else None

        wh_value = row.get(cmap["working_hours"]) if "working_hours" in cmap else None
        working_hours = _hours_value(wh_value)

        # If punches are complete but the file says 00:00, calculate actual duration.
        if working_hours <= 0:
            tin = _time_text(time_in_value)
            tout = _time_text(time_out_value)
            if tin and tout and tin != "00:00" and tout != "00:00":
                working_hours = _time_difference_hours(time_in_value, time_out_value)

        raw_status = row.get(cmap["status"]) if "status" in cmap else ""
        status = _map_attendance_status(
            raw_status, working_hours, time_in_value, time_out_value, day_name
        )

        shift_value = _clean_text(row.get(cmap["shift"])) if "shift" in cmap else ""
        if shift_value.upper() in {"A", "B"}:
            shift = shift_value.upper()
        elif shift_value.lower() == "general":
            shift = "General"
        else:
            shift = _infer_shift(time_in_value, row_div, time_out_value)

        # Locked policy: single OT only after 12 hours.
        ot_hours = (
            max(0.0, working_hours - get_setting_float("ot_threshold_hours", 12.0))
            if status in ("Present", "Half Day")
            else 0.0
        )

        employee_name = (
            _clean_text(row.get(cmap["employee_name"]))
            if "employee_name" in cmap else emp_id
        )
        designation = (
            _clean_text(row.get(cmap["designation"]))
            if "designation" in cmap else ""
        )
        remark = (
            _clean_text(row.get(cmap["remark"]))
            if "remark" in cmap else ""
        )

        records.append({
            "division": row_div,
            "employee_id": emp_id,
            "employee_name": employee_name or emp_id,
            "designation": designation,
            "work_date": work_date,
            "day_name": day_name,
            "time_in": _time_text(time_in_value),
            "time_out": _time_text(time_out_value),
            "working_hours": round(working_hours, 2),
            "raw_status": _clean_text(raw_status),
            "status": status,
            "remark": remark,
            "shift": shift,
            "ot_hours": round(ot_hours, 2),
            "review_required": status == "HR Review",
        })

    if len(detected_divisions) > 1:
        raise ValueError(
            "This attendance file contains more than one Division. "
            "Upload one division at a time."
        )

    if not records:
        if target_date is not None:
            raise ValueError(
                f"No attendance rows were found for {target_date.strftime('%d %b %Y')}. "
                "Check the selected date and the Date column in your file."
            )
        raise ValueError(
            "No valid attendance rows were found. "
            "Use the Reliable Packaging attendance template or the supported legacy export."
        )

    source_label = "Reliable Standard Attendance"
    if target_date is not None:
        source_label += " - Daily"
    else:
        source_label += " - Bulk"

    if dry_run:
        return 0, pd.DataFrame(records)
    saved = _bulk_upsert_attendance(records, source_label, replace_scope=replace_scope)
    return saved, pd.DataFrame(records)


def import_dhaulana_attendance_excel(uploaded_file, target_date=None, dry_run=False, start_date=None, end_date=None, replace_scope=False):
    wb = load_workbook(uploaded_file, data_only=True, read_only=False)
    ws = wb[wb.sheetnames[0]]
    base_date = ws.cell(1, 1).value
    if isinstance(base_date, datetime):
        base_date = base_date.date()
    if not isinstance(base_date, date):
        raise ValueError("Unable to identify the attendance month from cell A1.")
    day_columns = []
    for col in range(4, ws.max_column + 1):
        value = ws.cell(3, col).value
        try:
            day_number = int(float(value))
        except Exception:
            continue
        if 1 <= day_number <= 31:
            if target_date is not None:
                if target_date.year != base_date.year or target_date.month != base_date.month:
                    continue
                if day_number != target_date.day:
                    continue
            day_columns.append((col, day_number, _clean_text(ws.cell(2, col).value)))
    records = []
    row_num = 4
    while row_num <= ws.max_row:
        marker = _clean_text(ws.cell(row_num, 3).value).lower().replace(" ", "_")
        emp_id = _clean_code(ws.cell(row_num, 2).value)
        if marker == "in_time" and emp_id:
            employee_name = _clean_text(ws.cell(row_num + 1, 2).value) or emp_id
            for col, day_number, sheet_day in day_columns:
                try:
                    work_date = date(base_date.year, base_date.month, day_number)
                except ValueError:
                    continue
                if start_date is not None and work_date < start_date:
                    continue
                if end_date is not None and work_date > end_date:
                    continue
                time_in_value = ws.cell(row_num, col).value
                time_out_value = ws.cell(row_num + 1, col).value
                working_hours = _time_difference_hours(time_in_value, time_out_value)
                day_name = sheet_day or work_date.strftime("%a")
                status = _map_attendance_status("", working_hours, time_in_value, time_out_value, day_name)
                ot_hours = max(0.0, working_hours - get_setting_float("ot_threshold_hours", 12.0)) if status == "Present" else 0.0
                records.append({
                    "division": "Dhaulana Glass Plant",
                    "employee_id": emp_id,
                    "employee_name": employee_name,
                    "designation": "",
                    "work_date": work_date.isoformat(),
                    "day_name": day_name,
                    "time_in": _time_text(time_in_value),
                    "time_out": _time_text(time_out_value),
                    "working_hours": round(working_hours, 2),
                    "raw_status": "Derived",
                    "status": status,
                    "remark": "",
                    "shift": "General",
                    "ot_hours": round(ot_hours, 2),
                    "review_required": status == "HR Review",
                })
            row_num += 4
        else:
            row_num += 1
    if not records:
        if target_date is not None:
            raise ValueError(
                f"No Dhaulana attendance rows were found for {target_date.strftime('%d %b %Y')}. "
                f"This workbook is for {base_date.strftime('%b %Y')}. "
                "Select a date from the same month as the workbook."
            )
        raise ValueError(
            "No Dhaulana attendance rows were found. Expected the monthly horizontal "
            "In_Time / Out_Time format."
        )
    source_label = "Dhaulana Daily Import" if target_date is not None else "Dhaulana Monthly Import"
    if dry_run:
        return 0, pd.DataFrame(records)
    saved = _bulk_upsert_attendance(records, source_label, replace_scope=replace_scope)
    return saved, pd.DataFrame(records)


def attendance_precheck(preview_df):
    """Preview attendance and route only genuine master exceptions to HR Review.

    Employees already marked Inactive/Left/Resigned/Terminated are shown separately
    and skipped from attendance import. They are never recreated as temporary HR
    Review employees.
    """
    result = {
        "rows_ready": 0, "employees": 0, "dates": 0, "duplicates": 0,
        "unknown_ids": [], "division_mismatches": [], "inactive_ids": [],
        "inactive_rows": 0, "hr_review": 0,
        "master_exception_rows": 0, "status_summary": pd.DataFrame()
    }
    if preview_df is None or preview_df.empty:
        return result

    df = preview_df.copy()
    result["employees"] = int(df["employee_id"].astype(str).nunique())
    result["dates"] = int(df["work_date"].astype(str).nunique())
    dup_mask = df.duplicated(subset=["work_date","shift","employee_id"], keep=False)
    result["duplicates"] = int(dup_mask.sum())

    master = read_df("SELECT employee_id,division,department,status FROM employees")
    master_map = {}
    if not master.empty:
        master_map = {
            str(r["employee_id"]).strip(): {
                "division": _clean_text(r.get("division")),
                "department": _clean_text(r.get("department")),
                "status": _clean_text(r.get("status")),
            }
            for _, r in master.iterrows()
        }

    unknown, mismatch, inactive = [], [], []
    exception_mask, inactive_mask = [], []
    for _, r in df.iterrows():
        eid = str(r.get("employee_id","")).strip()
        div = _clean_text(r.get("division"))
        has_issue = False
        is_inactive = False
        emp_master = master_map.get(eid)
        master_status = _clean_text(emp_master.get("status")) .upper() if emp_master else ""

        if emp_master and master_status in {"INACTIVE", "LEFT", "RESIGNED", "TERMINATED"}:
            inactive.append(eid)
            is_inactive = True
        elif not emp_master or emp_master.get("department", "").upper() == "HR REVIEW":
            unknown.append(eid)
            has_issue = True
        elif emp_master.get("division") and div and emp_master.get("division") != div:
            mismatch.append(f"{eid}: master={emp_master.get('division')}, file={div}")
            has_issue = True

        exception_mask.append(has_issue)
        inactive_mask.append(is_inactive)

    result["unknown_ids"] = sorted(set(x for x in unknown if x))
    result["division_mismatches"] = sorted(set(mismatch))
    result["inactive_ids"] = sorted(set(x for x in inactive if x))

    exception_series = pd.Series(exception_mask, index=df.index, dtype=bool)
    inactive_series = pd.Series(inactive_mask, index=df.index, dtype=bool)
    result["inactive_rows"] = int(inactive_series.sum())
    result["master_exception_rows"] = int(exception_series.sum())

    biometric_review = df["status"].astype(str).eq("HR Review") & ~inactive_series
    result["hr_review"] = int((biometric_review | exception_series).sum())
    result["rows_ready"] = max(0, len(df) - result["duplicates"] - result["inactive_rows"])

    display_status = df.loc[~inactive_series, "status"].astype(str).copy()
    display_exceptions = exception_series.loc[display_status.index]
    display_status.loc[display_exceptions] = "HR Review"
    result["status_summary"] = (
        display_status.value_counts()
        .rename_axis("Status")
        .reset_index(name="Rows")
        .sort_values("Status")
    )
    return result

def import_salary_master_excel(uploaded_file, division):
    """
    Legacy XLSX compatibility importer.
    V6.9 safety rule: Salary import NEVER creates employees and NEVER changes
    Employee Name / Department / Designation / Division / Joining Date.
    Employee Master remains the single source of employee identity.
    """
    division = _normalize_master_division(division, fallback=division)

    if division == "Dhaulana Glass Plant":
        df = pd.read_excel(
            uploaded_file, header=1, engine="openpyxl",
            dtype={"E-code": str, "IFSC CODE": str, "A/C NUMBER": str}
        )
        rows = []
        for _, row in df.iterrows():
            emp_id = _clean_code(row.get("E-code"))
            if not emp_id or not any(ch.isdigit() for ch in emp_id):
                continue
            salary = _num(row.get("Salary Rate"), 0)
            rows.append({
                "employee_id": emp_id,
                "revised_salary_rate": salary,
                "increment_amount": 0.0,
                "monthly_salary": salary,
                "basic_vda": 0.0,
                "hra": 0.0,
                "conveyance": 0.0,
                "other_allowance": salary,
                "gross_pay": salary,
                "additional_fixed_allowance": _num(row.get("ADDITIONAL ALLOWANCE"), 0),
                "pf_applicable": False,
                "esic_applicable": False,
                "uan_number": "",
                "esic_number": "",
                "pan_number": "",
                "bank_name": _clean_text(row.get("Unnamed: 3")),
                "ifsc_code": _clean_code(row.get("IFSC CODE")),
                "bank_account": _clean_code(row.get("A/C NUMBER")),
            })
    else:
        _salary_code_dtypes = {
            "E-code": str, "PAN_Number": str,
            "IFSC CODE": str, "A/C NUMBER": str
        }
        if division == "Greater Noida Plant":
            _salary_code_dtypes.update({"UAN NUMBER": str, "ESIC_NUMBER": str})
        else:
            _salary_code_dtypes.update({"UAN Number": str, "ESIC_Number": str})

        df = pd.read_excel(
            uploaded_file, header=0, engine="openpyxl",
            dtype=_salary_code_dtypes
        )
        rows = []
        for _, row in df.iterrows():
            emp_id = _clean_code(row.get("E-code"))
            if not emp_id or not any(ch.isdigit() for ch in emp_id):
                continue

            uan = _clean_code(row.get("UAN NUMBER", row.get("UAN Number")))
            esic = _clean_code(row.get("ESIC_NUMBER", row.get("ESIC_Number")))
            revised = _num(row.get("Revised Salary Rate"), 0)
            increment = _num(row.get("Increment"), 0)
            monthly_salary = _num(row.get("Total"), revised + increment)
            gross_pay = _num(row.get("Gross Pay"), monthly_salary)

            rows.append({
                "employee_id": emp_id,
                "revised_salary_rate": revised,
                "increment_amount": increment,
                "monthly_salary": monthly_salary,
                "basic_vda": _num(row.get("Basic+Vda"), 0),
                "hra": _num(row.get("Hra"), 0),
                "conveyance": _num(row.get("Conveyance"), 0),
                "other_allowance": _num(row.get("Other Allow"), 0),
                "gross_pay": gross_pay,
                "additional_fixed_allowance": _num(row.get("Additional Fixed Allow ( If Any )"), 0),
                "pf_applicable": bool(uan and "EXEMPT" not in uan.upper()),
                "esic_applicable": bool(
                    esic
                    and "OUT OF COVERAGE" not in esic.upper()
                    and "NOT REGISTERED" not in esic.upper()
                    and "EXEMPT" not in esic.upper()
                ),
                "uan_number": uan,
                "esic_number": esic,
                "pan_number": _clean_code(row.get("PAN_Number")),
                "bank_name": _clean_text(row.get("Bank Name")),
                "ifsc_code": _clean_code(row.get("IFSC CODE")),
                "bank_account": _clean_code(row.get("A/C NUMBER")),
            })

    if not rows:
        raise ValueError("No valid salary rows were found in the workbook.")

    employee_master = read_df(
        "SELECT employee_id,employee_name,division FROM employees"
    )
    master_map = {
        str(r["employee_id"]).strip(): r.to_dict()
        for _, r in employee_master.iterrows()
    } if not employee_master.empty else {}

    missing = []
    mismatches = []
    valid_rows = []

    for rec in rows:
        eid = str(rec["employee_id"]).strip()
        emp = master_map.get(eid)
        if not emp:
            missing.append(eid)
            continue
        master_div = _clean_text(emp.get("division"))
        if master_div != division:
            mismatches.append(
                f"{eid}: Employee Master={master_div}, Salary file={division}"
            )
            continue
        rec["employee_name"] = _clean_text(emp.get("employee_name")) or eid
        valid_rows.append(rec)

    if missing or mismatches:
        parts = []
        if missing:
            shown = ", ".join(sorted(set(missing))[:20])
            more = f" (+{len(set(missing))-20} more)" if len(set(missing)) > 20 else ""
            parts.append(
                f"{len(set(missing))} salary Employee ID(s) are not in Employee Master: {shown}{more}"
            )
        if mismatches:
            shown = " | ".join(mismatches[:12])
            more = f" (+{len(mismatches)-12} more)" if len(mismatches) > 12 else ""
            parts.append(f"Division mismatch: {shown}{more}")
        raise ValueError(
            ". ".join(parts)
            + ". Salary import is update-only; correct Employee Master first."
        )

    conn = get_pg_conn()
    try:
        cur = conn.cursor()
        for rec in valid_rows:
            cur.execute(
                """UPDATE employees SET
                   revised_salary_rate=%s,
                   increment_amount=%s,
                   monthly_salary=%s,
                   basic_vda=%s,
                   hra=%s,
                   conveyance=%s,
                   other_allowance=%s,
                   gross_pay=%s,
                   additional_fixed_allowance=%s,
                   pf_applicable=%s,
                   esic_applicable=%s,
                   uan_number=CASE WHEN %s<>'' THEN %s ELSE uan_number END,
                   esic_number=CASE WHEN %s<>'' THEN %s ELSE esic_number END,
                   pan_number=CASE WHEN %s<>'' THEN %s ELSE pan_number END,
                   bank_name=CASE WHEN %s<>'' THEN %s ELSE bank_name END,
                   ifsc_code=CASE WHEN %s<>'' THEN %s ELSE ifsc_code END,
                   bank_account=CASE WHEN %s<>'' THEN %s ELSE bank_account END,
                   salary_active=TRUE
                   WHERE employee_id=%s AND division=%s""",
                (
                    rec["revised_salary_rate"],
                    rec["increment_amount"],
                    rec["monthly_salary"],
                    rec["basic_vda"],
                    rec["hra"],
                    rec["conveyance"],
                    rec["other_allowance"],
                    rec["gross_pay"],
                    rec["additional_fixed_allowance"],
                    rec["pf_applicable"],
                    rec["esic_applicable"],
                    rec["uan_number"], rec["uan_number"],
                    rec["esic_number"], rec["esic_number"],
                    rec["pan_number"], rec["pan_number"],
                    rec["bank_name"], rec["bank_name"],
                    rec["ifsc_code"], rec["ifsc_code"],
                    rec["bank_account"], rec["bank_account"],
                    rec["employee_id"], division,
                )
            )
        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

    preview = pd.DataFrame(valid_rows)
    return len(valid_rows), preview



def _get_payroll_adjustments(payroll_month, division=None):
    sql = "SELECT * FROM payroll_adjustments WHERE payroll_month = ?"
    params = [_month_key(payroll_month)]
    if division and division != ALL_DIVISIONS:
        sql += " AND division = ?"
        params.append(division)
    return read_df(sql, tuple(params))


def calculate_live_payroll(payroll_month, division=ALL_DIVISIONS):
    first_day, last_day = _month_range(payroll_month)
    calendar_days = (last_day - first_day).days + 1
    today = date.today()
    if today < first_day:
        as_of = first_day - timedelta(days=1)
    elif today > last_day:
        as_of = last_day
    else:
        as_of = today

    employee_sql = """
        SELECT employee_id, employee_name, division, department, designation, joining_date,
               monthly_salary, revised_salary_rate, basic_vda, hra, conveyance, other_allowance,
               gross_pay, additional_fixed_allowance, pf_applicable, esic_applicable, salary_active
        FROM employees
        WHERE status='Active' AND COALESCE(salary_active, TRUE)=TRUE
    """
    params = []
    if division != ALL_DIVISIONS:
        employee_sql += " AND division = ?"
        params.append(division)
    employee_sql += " ORDER BY division, employee_name"
    employees = read_df(employee_sql, tuple(params))
    if employees.empty:
        return pd.DataFrame()

    att_sql = """
        SELECT employee_id, division, work_date, status, working_hours, ot_hours
        FROM attendance
        WHERE work_date BETWEEN ? AND ?
    """
    att_params = [first_day.isoformat(), last_day.isoformat()]
    if division != ALL_DIVISIONS:
        att_sql += " AND division = ?"
        att_params.append(division)
    attendance = read_df(att_sql, tuple(att_params))
    adjustments = _get_payroll_adjustments(payroll_month, division)
    adj_map = {}
    if not adjustments.empty:
        for _, row in adjustments.iterrows():
            adj_map[(str(row["division"]), str(row["employee_id"]))] = row.to_dict()

    rows = []
    for _, emp in employees.iterrows():
        emp_id = str(emp["employee_id"])
        emp_div = str(emp.get("division") or "Greater Noida Plant")
        if attendance.empty:
            emp_att = pd.DataFrame()
        else:
            emp_att = attendance[(attendance["employee_id"].astype(str) == emp_id) & (attendance["division"].astype(str) == emp_div)].copy()
        if not emp_att.empty:
            emp_att["work_date_dt"] = pd.to_datetime(emp_att["work_date"], errors="coerce").dt.date
            emp_att = emp_att[emp_att["work_date_dt"] <= as_of].copy() if as_of >= first_day else emp_att.iloc[0:0]

        join_date = pd.to_datetime(emp.get("joining_date"), errors="coerce")
        eligible_start = first_day
        if not pd.isna(join_date) and join_date.date() > eligible_start:
            eligible_start = join_date.date()
        eligible_elapsed = max(0, (as_of - eligible_start).days + 1) if as_of >= eligible_start else 0

        status_counts = emp_att["status"].astype(str).value_counts().to_dict() if not emp_att.empty else {}
        paid_days = float(sum(PAID_STATUS_FACTORS.get(str(s), 0.0) for s in emp_att["status"].astype(str))) if not emp_att.empty else 0.0
        present_days = float(status_counts.get("Present", 0)) + 0.5 * float(status_counts.get("Half Day", 0))
        weekly_off_days = float(status_counts.get("WO", 0))
        paid_leave_days = float(status_counts.get("CL", 0) + status_counts.get("SL", 0) + status_counts.get("EL", 0) + status_counts.get("Leave", 0))
        lwp_days = float(status_counts.get("LWP", 0) + status_counts.get("Absent", 0))
        review_days = float(status_counts.get("HR Review", 0))
        attendance_records = int(emp_att["work_date"].nunique()) if not emp_att.empty else 0
        missing_days = max(0.0, float(eligible_elapsed - attendance_records))
        ot_hours = float(pd.to_numeric(emp_att.get("ot_hours", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if not emp_att.empty else 0.0

        monthly_salary = _num(emp.get("monthly_salary"), 0)
        gross_monthly = _num(emp.get("gross_pay"), monthly_salary) or monthly_salary
        basic_monthly = _num(emp.get("basic_vda"), 0)
        ratio = paid_days / calendar_days if calendar_days else 0.0
        gross_earned = gross_monthly * ratio
        basic_earned = basic_monthly * ratio

        # V6.7: fixed allowance follows PAID DAYS.
        # It must never create a payable salary while attendance is missing.
        fixed_monthly = _num(emp.get("additional_fixed_allowance"), 0)
        additional_fixed_earned = fixed_monthly * ratio

        daily_salary_rate = monthly_salary / calendar_days if calendar_days else 0.0
        ot_hourly_rate = daily_salary_rate / get_setting_float("ot_threshold_hours", 12.0) if daily_salary_rate else 0.0
        ot_pay = ot_hours * ot_hourly_rate * get_setting_float("ot_multiplier", 1.0)

        adj = adj_map.get((emp_div, emp_id), {})
        performance_incentive = _num(adj.get("performance_incentive"), 0)
        attendance_bonus = _num(adj.get("attendance_bonus"), 0)
        endorsement_allowance = _num(adj.get("endorsement_allowance"), 0)
        tds = _num(adj.get("tds"), 0)
        other_deduction = _num(adj.get("other_deduction"), 0)
        advance = _num(adj.get("advance"), 0)
        fine = _num(adj.get("fine"), 0)
        fooding = _num(adj.get("fooding"), 0)

        pf_auto = 0.0
        if bool(emp.get("pf_applicable")):
            prorated_ceiling = get_setting_float("pf_wage_ceiling", 15000.0) * ratio
            pf_auto = min(basic_earned, prorated_ceiling) * (get_setting_float("pf_employee_rate_pct", 12.0) / 100.0)
        esic_auto = gross_earned * (get_setting_float("esic_employee_rate_pct", 0.75) / 100.0) if bool(emp.get("esic_applicable")) else 0.0

        pf_override = adj.get("pf_override") if adj else None
        esic_override = adj.get("esic_override") if adj else None
        pf = pf_auto if pf_override is None or pd.isna(pf_override) else _num(pf_override, pf_auto)
        esic = esic_auto if esic_override is None or pd.isna(esic_override) else _num(esic_override, esic_auto)

        total_payable = gross_earned + additional_fixed_earned + ot_pay + performance_incentive + attendance_bonus + endorsement_allowance
        total_deduction = pf + esic + tds + other_deduction + advance + fine + fooding

        # V6.7 payroll safety:
        # Do not present a monetary "live net payable" until attendance is complete
        # and all HR Review exceptions are resolved.
        calculated_net_payable = total_payable - total_deduction
        attendance_blocked = (missing_days > 0) or (review_days > 0)
        net_payable = 0.0 if attendance_blocked else calculated_net_payable

        coverage_pct = (attendance_records / eligible_elapsed * 100.0) if eligible_elapsed else 0.0
        rows.append({
            "Division": emp_div,
            "Employee ID": emp_id,
            "Employee Name": str(emp.get("employee_name") or ""),
            "Department": str(emp.get("department") or ""),
            "Designation": str(emp.get("designation") or ""),
            "Monthly Salary": round(monthly_salary, 2),
            "Calendar Days": calendar_days,
            "Attendance Records": attendance_records,
            "Coverage %": round(coverage_pct, 2),
            "Paid Days": round(paid_days, 2),
            "Present Days": round(present_days, 2),
            "WO": round(weekly_off_days, 2),
            "Paid Leave": round(paid_leave_days, 2),
            "LWP/Absent": round(lwp_days, 2),
            "HR Review": round(review_days, 2),
            "Missing Days": round(missing_days, 2),
            "OT Hours": round(ot_hours, 2),
            "Gross Earned": round(gross_earned, 2),
            "Fixed Allowance Earned": round(additional_fixed_earned, 2),
            "OT Pay": round(ot_pay, 2),
            "Performance Incentive": round(performance_incentive, 2),
            "Attendance Bonus": round(attendance_bonus, 2),
            "Endorsement Allowance": round(endorsement_allowance, 2),
            "Total Payable": round(total_payable, 2),
            "PF": round(pf, 2),
            "ESIC": round(esic, 2),
            "TDS": round(tds, 2),
            "Advance": round(advance, 2),
            "Other Deduction": round(other_deduction, 2),
            "Fine": round(fine, 2),
            "Fooding": round(fooding, 2),
            "Total Deduction": round(total_deduction, 2),
            "Calculated Net": round(calculated_net_payable, 2),
            "Net Payable": round(net_payable, 2),
            "Payroll State": "HR Review" if review_days > 0 else ("Pending Attendance" if missing_days > 0 else "Ready"),
        })
    return pd.DataFrame(rows)


def save_payroll_adjustment(payroll_month, division, employee_id, values, updated_by):
    upsert("""
        INSERT INTO payroll_adjustments(
            payroll_month, division, employee_id, performance_incentive, attendance_bonus,
            endorsement_allowance, tds, other_deduction, advance, fine, fooding,
            pf_override, esic_override, remark, updated_by, updated_at
        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)
        ON CONFLICT(payroll_month, division, employee_id) DO UPDATE SET
            performance_incentive=excluded.performance_incentive,
            attendance_bonus=excluded.attendance_bonus,
            endorsement_allowance=excluded.endorsement_allowance,
            tds=excluded.tds,
            other_deduction=excluded.other_deduction,
            advance=excluded.advance,
            fine=excluded.fine,
            fooding=excluded.fooding,
            pf_override=excluded.pf_override,
            esic_override=excluded.esic_override,
            remark=excluded.remark,
            updated_by=excluded.updated_by,
            updated_at=CURRENT_TIMESTAMP
    """, (
        _month_key(payroll_month), division, employee_id,
        values.get("performance_incentive", 0), values.get("attendance_bonus", 0), values.get("endorsement_allowance", 0),
        values.get("tds", 0), values.get("other_deduction", 0), values.get("advance", 0), values.get("fine", 0),
        values.get("fooding", 0), values.get("pf_override"), values.get("esic_override"), values.get("remark", ""), updated_by,
    ))


def finalize_payroll(payroll_month, division, payroll_df, finalized_by):
    if payroll_df.empty:
        raise ValueError("No payroll rows are available to finalize.")
    blocking = payroll_df[(payroll_df["HR Review"] > 0) | (payroll_df["Missing Days"] > 0)]
    if not blocking.empty:
        raise ValueError(f"Payroll cannot be finalized: {len(blocking)} employee(s) still have HR Review or missing attendance days.")
    month_key = _month_key(payroll_month)
    conn = get_pg_conn()
    try:
        cur = conn.cursor()
        for _, row in payroll_df.iterrows():
            cur.execute("""
                INSERT INTO payroll_records(
                    payroll_month, division, employee_id, employee_name, designation, department,
                    monthly_salary, calendar_days, attendance_records, paid_days, present_days,
                    weekly_off_days, paid_leave_days, lwp_days, review_days, missing_days, ot_hours,
                    gross_earned, additional_fixed_earned, ot_pay, performance_incentive,
                    attendance_bonus, endorsement_allowance, total_payable, pf, esic, tds,
                    advance, other_deduction, fine, fooding, total_deduction, net_payable,
                    payroll_status, finalized_by, finalized_at
                ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,'Finalized',%s,CURRENT_TIMESTAMP)
                ON CONFLICT(payroll_month, division, employee_id) DO UPDATE SET
                    employee_name=excluded.employee_name, designation=excluded.designation, department=excluded.department,
                    monthly_salary=excluded.monthly_salary, calendar_days=excluded.calendar_days,
                    attendance_records=excluded.attendance_records, paid_days=excluded.paid_days,
                    present_days=excluded.present_days, weekly_off_days=excluded.weekly_off_days,
                    paid_leave_days=excluded.paid_leave_days, lwp_days=excluded.lwp_days,
                    review_days=excluded.review_days, missing_days=excluded.missing_days,
                    ot_hours=excluded.ot_hours, gross_earned=excluded.gross_earned,
                    additional_fixed_earned=excluded.additional_fixed_earned, ot_pay=excluded.ot_pay,
                    performance_incentive=excluded.performance_incentive,
                    attendance_bonus=excluded.attendance_bonus, endorsement_allowance=excluded.endorsement_allowance,
                    total_payable=excluded.total_payable, pf=excluded.pf, esic=excluded.esic,
                    tds=excluded.tds, advance=excluded.advance, other_deduction=excluded.other_deduction,
                    fine=excluded.fine, fooding=excluded.fooding, total_deduction=excluded.total_deduction,
                    net_payable=excluded.net_payable, payroll_status='Finalized',
                    finalized_by=excluded.finalized_by, finalized_at=CURRENT_TIMESTAMP
            """, (
                month_key, row["Division"], row["Employee ID"], row["Employee Name"], row["Designation"], row["Department"],
                row["Monthly Salary"], int(row["Calendar Days"]), int(row["Attendance Records"]), row["Paid Days"], row["Present Days"],
                row["WO"], row["Paid Leave"], row["LWP/Absent"], row["HR Review"], row["Missing Days"], row["OT Hours"],
                row["Gross Earned"], row["Fixed Allowance Earned"], row["OT Pay"], row["Performance Incentive"],
                row["Attendance Bonus"], row["Endorsement Allowance"], row["Total Payable"], row["PF"], row["ESIC"], row["TDS"],
                row["Advance"], row["Other Deduction"], row["Fine"], row["Fooding"], row["Total Deduction"], row["Net Payable"], finalized_by,
            ))
        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return len(payroll_df)


def contractor_month_summary(month_value):
    first_day, last_day = _month_range(month_value)
    return read_df("""
        SELECT c.vendor_name, c.thekedar_name, e.work_type, e.unit,
               SUM(e.quantity) AS quantity, AVG(e.rate) AS avg_rate, SUM(e.amount) AS amount
        FROM contractor_work_entries e
        JOIN contractors c ON c.contractor_id=e.contractor_id
        WHERE e.work_date BETWEEN ? AND ? AND e.division='Greater Noida Plant'
        GROUP BY c.vendor_name, c.thekedar_name, e.work_type, e.unit
        ORDER BY c.vendor_name, c.thekedar_name, e.work_type
    """, (first_day.isoformat(), last_day.isoformat()))


def get_machine_shift_target(machine, shift):
    df = read_df(
        """
        SELECT standard_manpower, target_ton
        FROM machine_shift_targets
        WHERE machine = ? AND shift = ?
        LIMIT 1
        """,
        (machine, shift),
    )
    if not df.empty:
        return int(df.iloc[0]["standard_manpower"] or 0), float(df.iloc[0]["target_ton"] or 0)
    base = read_df(
        "SELECT standard_manpower, target_ton FROM machines WHERE machine = ? LIMIT 1",
        (machine,),
    )
    if base.empty:
        return 0, 0.0
    return int(base.iloc[0]["standard_manpower"] or 0), float(base.iloc[0]["target_ton"] or 0)


def attendance_cost_factor(status):
    status = str(status)
    if status == "Half Day":
        return get_setting_float("half_day_cost_factor", 0.5)
    if status in {"Present", "WO", "Holiday", "CL", "SL", "EL", "Leave"}:
        return 1.0
    return 0.0


def make_excel_report(df, report_title, filters_text=""):
    """Create a branded Excel download without changing the database."""
    # V6.7: exported reports also carry a visible serial number.
    df = df.copy()
    if "S.No" not in df.columns and "S.No." not in df.columns:
        df.insert(0, "S.No", range(1, len(df) + 1))

    wb = Workbook()
    ws = wb.active
    ws.title = "Report"

    # Logo is embedded in this app. If Excel image rendering is unavailable,
    # the text header still produces a valid workbook.
    try:
        logo_stream = BytesIO(base64.b64decode(LOGO_FULL_DATA_URI.split(",", 1)[1]))
        logo = XLImage(logo_stream)
        logo.width = 260
        logo.height = 100
        ws.add_image(logo, "A1")
    except Exception:
        pass

    max_col = max(len(df.columns), 6)
    ws.merge_cells(start_row=1, start_column=5, end_row=1, end_column=max_col)
    ws.cell(1, 5).value = COMPANY_NAME
    ws.cell(1, 5).font = Font(size=16, bold=True, color="E94220")
    ws.cell(1, 5).alignment = Alignment(horizontal="left")

    ws.merge_cells(start_row=2, start_column=5, end_row=2, end_column=max_col)
    ws.cell(2, 5).value = report_title
    ws.cell(2, 5).font = Font(size=13, bold=True, color="111827")

    ws.merge_cells(start_row=3, start_column=5, end_row=3, end_column=max_col)
    ws.cell(3, 5).value = filters_text
    ws.cell(3, 5).font = Font(size=9, color="64748B")

    header_row = 7
    header_fill = PatternFill("solid", fgColor="132238")
    header_font = Font(color="FFFFFF", bold=True)
    thin = Side(style="thin", color="D7DEE8")

    for col_idx, col_name in enumerate(df.columns, 1):
        cell = ws.cell(header_row, col_idx, str(col_name))
        cell.fill = header_fill
        cell.font = header_font
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = Border(bottom=thin)

    safe_df = df.copy()
    safe_df = safe_df.where(pd.notnull(safe_df), None)
    for row_idx, row in enumerate(safe_df.itertuples(index=False, name=None), header_row + 1):
        for col_idx, value in enumerate(row, 1):
            try:
                if pd.isna(value):
                    value = None
            except Exception:
                pass
            if hasattr(value, "item"):
                try:
                    value = value.item()
                except Exception:
                    pass
            cell = ws.cell(row_idx, col_idx, value)
            cell.alignment = Alignment(vertical="top", wrap_text=False)

    for col_idx, col_name in enumerate(df.columns, 1):
        sample = [str(col_name)] + [str(v) for v in df.iloc[:100, col_idx - 1].tolist() if pd.notna(v)]
        width = min(max(max((len(v) for v in sample), default=8) + 2, 10), 28)
        ws.column_dimensions[ws.cell(header_row, col_idx).column_letter].width = width

    ws.freeze_panes = f"A{header_row + 1}"
    ws.auto_filter.ref = f"A{header_row}:{ws.cell(header_row + max(len(df),1), max(len(df.columns),1)).coordinate}"
    ws.sheet_view.showGridLines = False

    output = BytesIO()
    wb.save(output)
    return output.getvalue()


def load_report_source(start_date, end_date, shift_filter="All", department_filter="All Department"):
    start_text = start_date.isoformat()
    end_text = end_date.isoformat()
    shift_sql = "" if shift_filter == "All" else " AND a.shift = ?"
    att_params = (start_text, end_text) if shift_filter == "All" else (start_text, end_text, shift_filter)
    attendance = read_df(
        f"""
        SELECT a.work_date, a.shift, a.employee_id, e.employee_name,
               e.department, e.designation, e.employee_type,
               a.status, a.ot_hours, e.monthly_salary, e.ot_rate, e.working_days
        FROM attendance a
        LEFT JOIN employees e ON e.employee_id = a.employee_id
        WHERE a.work_date BETWEEN ? AND ?{shift_sql}
        ORDER BY a.work_date, a.shift, e.department, e.employee_name
        """,
        att_params,
    )

    shift_sql_alloc = "" if shift_filter == "All" else " AND ma.shift = ?"
    alloc_params = (start_text, end_text) if shift_filter == "All" else (start_text, end_text, shift_filter)
    allocation = read_df(
        f"""
        SELECT ma.work_date, ma.shift, ma.machine, m.department,
               ma.employee_id, e.employee_name, e.designation, ma.role,
               e.monthly_salary, e.working_days, e.ot_rate
        FROM manpower_allocation ma
        LEFT JOIN employees e ON e.employee_id = ma.employee_id
        LEFT JOIN machines m ON m.machine = ma.machine
        WHERE ma.work_date BETWEEN ? AND ?{shift_sql_alloc}
        ORDER BY ma.work_date, ma.shift, ma.machine, e.employee_name
        """,
        alloc_params,
    )

    shift_sql_prod = "" if shift_filter == "All" else " AND p.shift = ?"
    prod_params = (start_text, end_text) if shift_filter == "All" else (start_text, end_text, shift_filter)
    production = read_df(
        f"""
        SELECT p.work_date, p.shift, p.machine, m.department,
               p.production_ton, p.target_ton, p.waste_ton, p.breakdown_hours,
               p.paper_cost, p.ink_cost, p.glue_cost, p.other_material_cost
        FROM production p
        LEFT JOIN machines m ON m.machine = p.machine
        WHERE p.work_date BETWEEN ? AND ?{shift_sql_prod}
        ORDER BY p.work_date, p.shift, p.machine
        """,
        prod_params,
    )

    employees = read_df("SELECT * FROM employees WHERE status='Active' ORDER BY department, employee_name")

    if department_filter != "All Department":
        if not attendance.empty:
            attendance = attendance[attendance["department"].astype(str) == department_filter].copy()
        if not allocation.empty:
            allocation = allocation[allocation["department"].astype(str) == department_filter].copy()
        if not production.empty:
            production = production[production["department"].astype(str) == department_filter].copy()
        if not employees.empty:
            employees = employees[employees["department"].astype(str) == department_filter].copy()

    return employees, attendance, allocation, production


def labour_cost_by_machine(attendance, allocation):
    if allocation.empty:
        return pd.DataFrame(columns=["work_date", "shift", "machine", "labour_cost", "ot_cost", "allocated_manpower"])
    alloc = allocation.copy()
    att = attendance[["work_date", "shift", "employee_id", "status", "ot_hours"]].copy() if not attendance.empty else pd.DataFrame(columns=["work_date","shift","employee_id","status","ot_hours"])
    merged = alloc.merge(att, on=["work_date", "shift", "employee_id"], how="left")
    merged["monthly_salary"] = pd.to_numeric(merged["monthly_salary"], errors="coerce").fillna(0.0)
    merged["working_days"] = pd.to_numeric(merged["working_days"], errors="coerce").replace(0, pd.NA)
    merged["ot_rate"] = pd.to_numeric(merged["ot_rate"], errors="coerce").fillna(0.0)
    merged["ot_hours"] = pd.to_numeric(merged["ot_hours"], errors="coerce").fillna(0.0)
    _cost_dates = pd.to_datetime(merged["work_date"], errors="coerce")
    merged["calendar_days"] = _cost_dates.map(lambda d: monthrange(d.year, d.month)[1] if not pd.isna(d) else 30)
    merged["daily_cost"] = (merged["monthly_salary"] / merged["calendar_days"]).fillna(0.0)
    merged["factor"] = merged["status"].fillna("Not Marked").map(attendance_cost_factor)
    merged["base_cost"] = merged["daily_cost"] * merged["factor"]
    merged["ot_cost"] = (merged["daily_cost"] / get_setting_float("ot_threshold_hours", 12.0)) * merged["ot_hours"] * get_setting_float("ot_multiplier", 1.0) * (merged["factor"] > 0).astype(int)
    merged["labour_cost"] = merged["base_cost"] + merged["ot_cost"]
    return merged.groupby(["work_date", "shift", "machine"], as_index=False).agg(
        labour_cost=("labour_cost", "sum"),
        ot_cost=("ot_cost", "sum"),
        allocated_manpower=("employee_id", "nunique"),
    )


def build_missing_data_report(start_date, end_date, shift_filter, employees, attendance, allocation, production):
    rows = []
    dates = pd.date_range(start_date, end_date, freq="D")
    shifts = [shift_filter] if shift_filter in ("A", "B") else ["A", "B"]
    machines = read_df("SELECT machine, department FROM machines ORDER BY machine")
    for d in dates:
        dtext = d.date().isoformat()
        for sh in shifts:
            expected = employees.copy()
            if not expected.empty and "shift" in expected.columns:
                specific = expected[expected["shift"].astype(str).str.upper() == sh]
                if not specific.empty:
                    expected = specific
            expected_count = len(expected)
            marked = attendance[(attendance["work_date"].astype(str) == dtext) & (attendance["shift"].astype(str) == sh)] if not attendance.empty else pd.DataFrame()
            if expected_count > 0 and len(marked) < expected_count:
                rows.append({"Date": dtext, "Shift": sh, "Scope": "Attendance", "Issue": f"{expected_count-len(marked)} employee(s) not marked"})
            for _, mrow in machines.iterrows():
                machine = str(mrow["machine"])
                arows = allocation[(allocation["work_date"].astype(str) == dtext) & (allocation["shift"].astype(str) == sh) & (allocation["machine"].astype(str) == machine)] if not allocation.empty else pd.DataFrame()
                prows = production[(production["work_date"].astype(str) == dtext) & (production["shift"].astype(str) == sh) & (production["machine"].astype(str) == machine)] if not production.empty else pd.DataFrame()
                if not arows.empty and prows.empty:
                    rows.append({"Date": dtext, "Shift": sh, "Scope": machine, "Issue": "Manpower allocated but production entry missing"})
                if arows.empty and not prows.empty and float(pd.to_numeric(prows["production_ton"], errors="coerce").fillna(0).sum()) > 0:
                    rows.append({"Date": dtext, "Shift": sh, "Scope": machine, "Issue": "Production entered but manpower allocation missing"})
    return pd.DataFrame(rows, columns=["Date", "Shift", "Scope", "Issue"])



