def get_previous_closing_wip(machine, work_date, shift):
    """Use previous shift/day closing WIP as the next conversion opening WIP suggestion."""
    df = read_df(
        """SELECT closing_wip_ton
           FROM production
           WHERE machine=? AND (
               work_date < ? OR (work_date=? AND shift < ?)
           )
           ORDER BY work_date DESC, shift DESC
           LIMIT 1""",
        (machine, work_date.isoformat(), work_date.isoformat(), shift)
    )
    if df.empty:
        return 0.0
    return float(df.iloc[0].get("closing_wip_ton") or 0)


def dashboard_data(report_date, selected_shift):
    date_text = report_date.isoformat()
    shift_filter = "" if selected_shift == "All" else " AND shift = ?"
    params = (date_text,) if selected_shift == "All" else (date_text, selected_shift)

    employees = read_df("SELECT * FROM employees WHERE status='Active'")
    for _col in ["monthly_salary", "ot_rate", "working_days"]:
        if _col in employees.columns:
            employees[_col] = pd.to_numeric(employees[_col], errors="coerce").fillna(0.0).astype(float)

    attendance = read_df(f"SELECT * FROM attendance WHERE work_date = ?{shift_filter}", params)
    allocations = read_df(f"SELECT * FROM manpower_allocation WHERE work_date = ?{shift_filter}", params)
    production = read_df(f"SELECT * FROM production WHERE work_date = ?{shift_filter}", params)
    machines = read_df("""SELECT * FROM machines WHERE COALESCE(active,TRUE)=TRUE ORDER BY machine""")
    shift_targets = read_df("SELECT * FROM machine_shift_targets")

    if attendance.empty:
        present_ids = set()
        absent_count = leave_count = half_day_count = wo_count = 0
        ot_cost = attendance_cost = 0.0
    else:
        work_status = attendance["status"].astype(str)
        present_ids = set(attendance.loc[work_status.isin(["Present", "Half Day"]), "employee_id"].astype(str))
        absent_count = int((work_status == "Absent").sum())
        leave_count = int((work_status == "Leave").sum())
        half_day_count = int((work_status == "Half Day").sum())
        wo_count = int((work_status == "WO").sum())
        cost_df = attendance.merge(
            employees[["employee_id", "monthly_salary", "ot_rate", "working_days"]],
            on="employee_id", how="left"
        )
        cost_df["monthly_salary"] = pd.to_numeric(cost_df["monthly_salary"], errors="coerce").fillna(0.0)
        cost_df["ot_hours"] = pd.to_numeric(cost_df["ot_hours"], errors="coerce").fillna(0.0)
        _calendar_days = monthrange(report_date.year, report_date.month)[1]
        cost_df["daily_cost"] = (cost_df["monthly_salary"] / _calendar_days).fillna(0.0)
        cost_df["factor"] = cost_df["status"].map(attendance_cost_factor)
        cost_df["attendance_cost"] = cost_df["daily_cost"] * cost_df["factor"]
        cost_df["ot_cost"] = (cost_df["daily_cost"] / get_setting_float("ot_threshold_hours", 12.0)) * cost_df["ot_hours"] * (cost_df["factor"] > 0).astype(int)
        attendance_cost = float(cost_df["attendance_cost"].sum())
        ot_cost = float(cost_df["ot_cost"].sum())

    total_labour_cost = attendance_cost + ot_cost

    if allocations.empty:
        alloc_summary = pd.DataFrame(columns=["machine", "actual_manpower"])
    else:
        alloc_summary = allocations.groupby("machine", as_index=False).agg(actual_manpower=("employee_id", "nunique"))

    prod_cols = [
        "production_ton","target_ton","waste_ton","breakdown_hours",
        "material_available_ton","material_processed_ton","good_output_ton",
        "closing_wip_ton"
    ]
    for c in prod_cols:
        if c not in production.columns:
            production[c] = 0.0
        production[c] = pd.to_numeric(production[c], errors="coerce").fillna(0.0)

    if production.empty:
        prod_summary = pd.DataFrame(columns=[
            "machine","production_ton","target_ton","waste_ton","breakdown_hours",
            "material_available_ton","material_processed_ton","good_output_ton","closing_wip_ton"
        ])
    else:
        prod_summary = production.groupby("machine", as_index=False).agg(
            production_ton=("production_ton","sum"),
            target_ton=("target_ton","sum"),
            waste_ton=("waste_ton","sum"),
            breakdown_hours=("breakdown_hours","sum"),
            material_available_ton=("material_available_ton","sum"),
            material_processed_ton=("material_processed_ton","sum"),
            good_output_ton=("good_output_ton","sum"),
            closing_wip_ton=("closing_wip_ton","sum"),
        )

    # Manpower standard per selected shift scope.
    if shift_targets.empty:
        target_summary = machines[["machine","standard_manpower"]].copy()
        multiplier = 2 if selected_shift == "All" else 1
        target_summary["standard_manpower_display"] = target_summary["standard_manpower"] * multiplier
        target_summary = target_summary[["machine","standard_manpower_display"]]
    else:
        scoped = shift_targets.copy()
        if selected_shift != "All":
            scoped = scoped[scoped["shift"].astype(str) == selected_shift]
        target_summary = scoped.groupby("machine", as_index=False).agg(
            standard_manpower_display=("standard_manpower","sum")
        )

    analysis = machines.merge(target_summary, on="machine", how="left").merge(
        alloc_summary, on="machine", how="left"
    ).merge(prod_summary, on="machine", how="left").fillna(0)

    # Fixed-ton target is Corrugation-style. Conversion target is 100% of available material.
    def _target_for_row(r):
        if str(r.get("target_type")) == "FIXED_TON":
            daily = float(r.get("daily_target_ton") or 0)
            return daily if selected_shift == "All" else daily / 2.0
        return 0.0

    analysis["target_ton_display"] = analysis.apply(_target_for_row, axis=1)
    analysis["conversion_pct"] = (
        analysis["material_processed_ton"] /
        analysis["material_available_ton"].replace(0, pd.NA) * 100
    ).fillna(0.0)
    analysis["yield_pct"] = (
        analysis["good_output_ton"] /
        analysis["material_processed_ton"].replace(0, pd.NA) * 100
    ).fillna(0.0)
    analysis["manpower_gap"] = analysis["actual_manpower"] - analysis["standard_manpower_display"]
    analysis["manpower_utilization"] = (
        analysis["actual_manpower"] / analysis["standard_manpower_display"].replace(0, pd.NA)
    ).fillna(0.0)
    analysis["efficiency"] = analysis.apply(
        lambda r: (
            float(r["production_ton"]) / float(r["target_ton_display"])
            if str(r.get("target_type")) == "FIXED_TON" and float(r["target_ton_display"]) > 0
            else float(r["conversion_pct"]) / 100.0
            if str(r.get("target_type")) == "MATERIAL_CONVERSION" and float(r["material_available_ton"]) > 0
            else 0.0
        ), axis=1
    )

    def status(r):
        actual_mp = float(r.get("actual_manpower") or 0)
        std_mp = float(r.get("standard_manpower_display") or 0)
        ttype = str(r.get("target_type") or "MATERIAL_CONVERSION")
        if ttype == "FIXED_TON":
            actual = float(r.get("production_ton") or 0)
            target = float(r.get("target_ton_display") or 0)
            if actual <= 0:
                return "No Production"
            if target > 0 and actual < target:
                return "Below Target"
        else:
            available = float(r.get("material_available_ton") or 0)
            processed = float(r.get("material_processed_ton") or 0)
            if available <= 0:
                return "No Material Released"
            if processed <= 0:
                return "Pending Conversion"
            if processed + 1e-9 < available:
                return "WIP Pending"
        if std_mp <= 0:
            return "Manpower Standard Not Set"
        if actual_mp <= 0:
            return "Review Manpower"
        if actual_mp > std_mp:
            return "Overstaffed"
        return "On Track"

    analysis["status"] = analysis.apply(status, axis=1)

    fixed = analysis[analysis["target_type"].astype(str) == "FIXED_TON"] if not analysis.empty else pd.DataFrame()
    conv = analysis[analysis["target_type"].astype(str) == "MATERIAL_CONVERSION"] if not analysis.empty else pd.DataFrame()
    total_production = float(pd.to_numeric(fixed.get("production_ton", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if not fixed.empty else 0.0
    total_target = float(pd.to_numeric(fixed.get("target_ton_display", pd.Series(dtype=float)), errors="coerce").fillna(0).sum()) if not fixed.empty else 0.0
    efficiency = total_production / total_target if total_target else 0.0
    avg_conversion = float(pd.to_numeric(conv.get("conversion_pct", pd.Series(dtype=float)), errors="coerce").fillna(0).mean()) if not conv.empty else 0.0
    avg_yield = float(pd.to_numeric(conv.get("yield_pct", pd.Series(dtype=float)), errors="coerce").fillna(0).mean()) if not conv.empty else 0.0
    cost_per_ton = total_labour_cost / total_production if total_production else 0.0

    return {
        "employees":employees,"attendance":attendance,"allocations":allocations,
        "production":production,"analysis":analysis,
        "present_count":len(present_ids),"absent_count":absent_count,
        "leave_count":leave_count,"half_day_count":half_day_count,"wo_count":wo_count,
        "attendance_cost":attendance_cost,"ot_cost":ot_cost,"total_labour_cost":total_labour_cost,
        "total_production":total_production,"total_target":total_target,
        "cost_per_ton":cost_per_ton,"efficiency":efficiency,
        "avg_conversion":avg_conversion,"avg_yield":avg_yield,
    }

