def v57_reset_all_business_data(reset_by):
    """
    Full business-data reset for a clean live start.

    Preserved deliberately:
      - app_users
      - app_user_permissions
      - app_sessions
      - app_settings (including security/business rules and fresh_start_reset_v1)

    Departments/machines are cleared and are NOT recreated automatically.
    Admin must build every business master from Master Centre.
    """
    conn = get_pg_conn()
    try:
        cur = conn.cursor()
        cur.execute("""
            TRUNCATE TABLE
                contractor_work_entries,
                contractor_rates,
                contractors,
                payroll_records,
                payroll_adjustments,
                attendance,
                manpower_allocation,
                production,
                machine_shift_targets,
                machines,
                employees,
                department_mappings,
                departments
            RESTART IDENTITY CASCADE
        """)
        cur.execute("""
            INSERT INTO app_settings(setting_key, setting_value)
            VALUES ('last_full_live_reset_by', %s)
            ON CONFLICT(setting_key)
            DO UPDATE SET setting_value=excluded.setting_value
        """, (str(reset_by or "Admin"),))
        cur.execute("""
            INSERT INTO app_settings(setting_key, setting_value)
            VALUES ('last_full_live_reset_at', CURRENT_TIMESTAMP::text)
            ON CONFLICT(setting_key)
            DO UPDATE SET setting_value=excluded.setting_value
        """)
        conn.commit()
        cur.close()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def v5_division_clause(division, prefix=""):
    col = f"{prefix}division" if prefix else "division"
    if division == ALL_DIVISIONS:
        return "", ()
    return f" AND {col} = ?", (division,)

def v5_active_employees(division=ALL_DIVISIONS):
    clause, params = v5_division_clause(division)
    return read_df(
        "SELECT * FROM employees WHERE status='Active' " + clause + " ORDER BY division, employee_name",
        params,
    )

def v5_attendance_for_date(work_date, division=ALL_DIVISIONS):
    clause, params = v5_division_clause(division)
    return read_df(
        """SELECT a.*, e.employee_name, e.department
           FROM attendance a
           LEFT JOIN employees e ON e.employee_id=a.employee_id
           WHERE a.work_date=? """ + clause.replace("division","a.division") + """
           ORDER BY a.division, e.employee_name""",
        (work_date.isoformat(),) + params,
    )

def v5_latest_attendance_status():
    employees = read_df(
        """SELECT division,
                  COUNT(*) AS employees,
                  SUM(CASE WHEN salary_active THEN 1 ELSE 0 END) AS payroll_active,
                  SUM(CASE WHEN COALESCE(monthly_salary,0)>0 OR COALESCE(gross_pay,0)>0 THEN 1 ELSE 0 END) AS salary_available
           FROM employees WHERE status='Active'
           GROUP BY division ORDER BY division"""
    )
    latest = read_df(
        """SELECT division, MAX(work_date) AS latest_attendance, COUNT(*) AS total_attendance_rows
           FROM attendance GROUP BY division"""
    )
    result = pd.DataFrame({"Division": DIVISIONS})
    if not employees.empty:
        result = result.merge(
            employees.rename(columns={
                "division":"Division",
                "employees":"Employees",
                "payroll_active":"Payroll Active",
                "salary_available":"Salary Available"
            }),
            on="Division", how="left"
        )
    if not latest.empty:
        result = result.merge(
            latest.rename(columns={"division":"Division","latest_attendance":"Latest Attendance","total_attendance_rows":"Attendance Rows"}),
            on="Division", how="left"
        )
    for c in ["Employees","Payroll Active","Salary Available","Attendance Rows"]:
        if c not in result: result[c]=0
        result[c]=pd.to_numeric(result[c],errors="coerce").fillna(0).astype(int)
    result["Salary Missing"] = (result["Employees"] - result["Salary Available"]).clip(lower=0)
    if "Latest Attendance" not in result: result["Latest Attendance"]=""
    result["Latest Attendance"]=result["Latest Attendance"].fillna("Not uploaded")
    return result

