UNIVERSAL_MASTER_COLUMNS = [
    "Row_Action","Master_Type","Division","Active",
    "Department","Machine","Shift","Standard_Manpower","Target_Ton",
    "Target_Type","Daily_Target_Ton","Conversion_Target_Pct","Shift_Target_Ton",
    "Vendor_Name","Thekedar_Name","Work_Type","Unit","Rate","Effective_From",
    "Employee_ID","Employee_Name","Father_Husband_Name","Designation",
    "Employee_Type","Default_Shift","Skill_Level","Joining_Date","Employee_Status",
    "Payroll_Active","Monthly_Salary","Revised_Salary_Rate","Increment","Gross_Pay",
    "Basic_VDA","HRA","Conveyance","Other_Allowance","Additional_Fixed_Allowance",
    "PF_Applicable","ESIC_Applicable","UAN_Number","ESIC_Number","PAN_Number",
    "Bank_Name","Bank_Account","IFSC","Mobile_Number","Email","HR_Remarks",
    "OT_Rate","Working_Days"
]

UNIVERSAL_MASTER_TYPES = [
    "DEPARTMENT","MACHINE","SHIFT_STANDARD","CONTRACTOR",
    "CONTRACTOR_RATE","EMPLOYEE","SALARY"
]


def _master_text(value, default=""):
    try:
        if value is None or pd.isna(value):
            return default
    except Exception:
        pass
    return str(value).strip()


def _master_bool(value, default=False):
    text = _master_text(value).lower()
    if text in {"1","true","yes","y","active","on"}:
        return True
    if text in {"0","false","no","n","inactive","off"}:
        return False
    return bool(default)


def _master_num(value, default=0.0):
    try:
        if value is None or pd.isna(value) or str(value).strip()=="":
            return float(default)
        return float(value)
    except Exception:
        return float(default)


def _master_int(value, default=0):
    try:
        return int(round(_master_num(value, default)))
    except Exception:
        return int(default)


