def _normalize_master_import_df(df):
    if df is None:
        return df
    out = df.copy()
    if "Division" in out.columns:
        out["Division"] = out["Division"].apply(
            lambda v: _normalize_master_division(v, fallback=_clean_text(v))
        )

    # Only employee records carry the employee department master.
    if "Department" in out.columns:
        mapping = _department_mapping_dict()
        if "Master_Type" in out.columns:
            mt = out["Master_Type"].astype(str).str.strip().str.upper()
            emp_mask = mt.eq("EMPLOYEE")
            out.loc[emp_mask, "Department"] = out.loc[emp_mask, "Department"].apply(
                lambda v: _normalize_department_value(v, mapping)
            )
    return out


def _master_employee_collision_errors(df):
    """Prevent a bulk import from silently moving the same Employee ID to another division."""
    if df is None or df.empty or "Master_Type" not in df.columns:
        return []
    relevant = df[
        df["Master_Type"].astype(str).str.strip().str.upper().isin(["EMPLOYEE","SALARY"])
    ].copy()
    if relevant.empty:
        return []

    existing = read_df("SELECT employee_id,division FROM employees")
    existing_map = {
        str(r["employee_id"]).strip(): _clean_text(r.get("division"))
        for _, r in existing.iterrows()
    } if not existing.empty else {}

    errors = []
    for idx, row in relevant.iterrows():
        eid = _master_text(row.get("Employee_ID"))
        div = _normalize_master_division(row.get("Division"), fallback=_master_text(row.get("Division")))
        if eid and eid in existing_map and existing_map[eid] and div and existing_map[eid] != div:
            errors.append(
                f"Row {idx+2}: Employee_ID {eid} already belongs to {existing_map[eid]}; "
                f"it cannot be imported into {div}. Employee IDs are globally unique."
            )
    return errors



def validate_universal_master_df(df):
    errors = []
    if df is None or df.empty:
        return ["CSV is empty."]
    df = _normalize_master_import_df(df)
    missing = [c for c in UNIVERSAL_MASTER_COLUMNS if c not in df.columns]
    if missing:
        errors.append("Missing required column(s): " + ", ".join(missing))
        return errors

    valid_divisions = set(DIVISIONS)
    valid_units = {"Pin","Sheet","Piece","Box","Job"}
    valid_shifts = {"A","B","General"}
    active_departments_df = read_df("SELECT department FROM departments WHERE active='Yes'")
    active_departments = set(
        active_departments_df["department"].astype(str).str.strip().tolist()
    ) if not active_departments_df.empty else set()
    errors.extend(_master_employee_collision_errors(df))

    for idx, row in df.iterrows():
        excel_row = idx + 2
        action = _master_text(row.get("Row_Action")).upper()
        if action == "IGNORE":
            continue
        master_type = _master_text(row.get("Master_Type")).upper()
        if not master_type:
            errors.append(f"Row {excel_row}: Master_Type is required.")
            continue
        if master_type not in UNIVERSAL_MASTER_TYPES:
            errors.append(
                f"Row {excel_row}: invalid Master_Type '{master_type}'. "
                f"Use {', '.join(UNIVERSAL_MASTER_TYPES)}."
            )
            continue

        division = _master_text(row.get("Division"))
        if master_type in {"CONTRACTOR","CONTRACTOR_RATE","EMPLOYEE","SALARY"}:
            if division not in valid_divisions:
                errors.append(f"Row {excel_row}: valid Division is required for {master_type}.")

        if master_type == "DEPARTMENT" and not _master_text(row.get("Department")):
            errors.append(f"Row {excel_row}: Department is required.")
        elif master_type == "MACHINE":
            if not _master_text(row.get("Machine")):
                errors.append(f"Row {excel_row}: Machine is required.")
            if not _master_text(row.get("Department")):
                errors.append(f"Row {excel_row}: Department is required for MACHINE.")
            target_type = _master_text(row.get("Target_Type")).upper().replace(" ", "_")
            if target_type and target_type not in {"FIXED_TON","MATERIAL_CONVERSION","100%_MATERIAL_CONVERSION"}:
                errors.append(f"Row {excel_row}: Target_Type must be FIXED_TON or MATERIAL_CONVERSION.")
            if target_type == "FIXED_TON" and _master_num(row.get("Daily_Target_Ton"), 0) <= 0:
                errors.append(f"Row {excel_row}: Daily_Target_Ton is required for FIXED_TON machines.")
        elif master_type == "SHIFT_STANDARD":
            if not _master_text(row.get("Machine")):
                errors.append(f"Row {excel_row}: Machine is required for SHIFT_STANDARD.")
            if _master_text(row.get("Shift")) not in {"A","B"}:
                errors.append(f"Row {excel_row}: Shift must be A or B.")
        elif master_type == "CONTRACTOR":
            if not _master_text(row.get("Vendor_Name")) or not _master_text(row.get("Thekedar_Name")):
                errors.append(f"Row {excel_row}: Vendor_Name and Thekedar_Name are required.")
        elif master_type == "CONTRACTOR_RATE":
            if not _master_text(row.get("Vendor_Name")) or not _master_text(row.get("Thekedar_Name")):
                errors.append(f"Row {excel_row}: Vendor_Name and Thekedar_Name are required.")
            if not _master_text(row.get("Work_Type")):
                errors.append(f"Row {excel_row}: Work_Type is required.")
            if _master_text(row.get("Unit")) not in valid_units:
                errors.append(f"Row {excel_row}: Unit must be Pin, Sheet, Piece, Box or Job.")
            if _master_num(row.get("Rate"), -1) < 0:
                errors.append(f"Row {excel_row}: Rate must be zero or greater.")
        elif master_type == "EMPLOYEE":
            for col in ["Employee_ID","Employee_Name","Department","Designation"]:
                if not _master_text(row.get(col)):
                    errors.append(f"Row {excel_row}: {col} is required for EMPLOYEE.")
            emp_dep = _master_text(row.get("Department"))
            if emp_dep and active_departments and emp_dep not in active_departments:
                errors.append(
                    f"Row {excel_row}: Department '{emp_dep}' is not in active Department Master. "
                    "Create a Department Mapping or correct the Employee Master."
                )
            if _master_text(row.get("Default_Shift"), "General") not in valid_shifts:
                errors.append(f"Row {excel_row}: Default_Shift must be General, A or B.")
        elif master_type == "SALARY":
            if not _master_text(row.get("Employee_ID")):
                errors.append(f"Row {excel_row}: Employee_ID is required for SALARY.")
    return errors


def import_universal_master_csv(df):
    df = _normalize_master_import_df(df)
    errors = validate_universal_master_df(df)
    if errors:
        raise ValueError("\\n".join(errors[:100]))

    working = df.copy()
    working["__action"] = working["Row_Action"].fillna("").astype(str).str.strip().str.upper()
    working["__type"] = working["Master_Type"].fillna("").astype(str).str.strip().str.upper()
    working = working[working["__action"] != "IGNORE"].copy()

    counts = {t: 0 for t in UNIVERSAL_MASTER_TYPES}
    row_errors = []

    # Import in dependency order.
    for master_type in UNIVERSAL_MASTER_TYPES:
        subset = working[working["__type"] == master_type]
        for idx, row in subset.iterrows():
            csv_row = idx + 2
            try:
                if master_type == "DEPARTMENT":
                    dep = _master_text(row.get("Department"))
                    active = "Yes" if _master_bool(row.get("Active"), True) else "No"
                    upsert(
                        """INSERT INTO departments(department,active) VALUES (?,?)
                           ON CONFLICT(department) DO UPDATE SET active=excluded.active""",
                        (dep, active)
                    )

                elif master_type == "MACHINE":
                    machine = _master_text(row.get("Machine"))
                    dep = _master_text(row.get("Department"))
                    raw_type = _master_text(row.get("Target_Type")).upper().replace(" ", "_")
                    if raw_type == "100%_MATERIAL_CONVERSION":
                        raw_type = "MATERIAL_CONVERSION"
                    if not raw_type:
                        raw_type = "FIXED_TON" if machine.strip().lower() == "corrugation" else "MATERIAL_CONVERSION"
                    daily_target = _master_num(row.get("Daily_Target_Ton"), 0)
                    if raw_type == "FIXED_TON" and daily_target <= 0 and machine.strip().lower() == "corrugation":
                        daily_target = 110.0
                    conversion_target = _master_num(row.get("Conversion_Target_Pct"), 100.0) or 100.0
                    legacy_shift_target = daily_target / 2.0 if raw_type == "FIXED_TON" else 0.0
                    upsert(
                        """INSERT INTO machines(
                           machine,department,standard_manpower,target_ton,target_type,
                           daily_target_ton,conversion_target_pct,active
                           ) VALUES (?,?,?,?,?,?,?,?)
                           ON CONFLICT(machine) DO UPDATE SET
                           department=excluded.department,
                           standard_manpower=excluded.standard_manpower,
                           target_ton=excluded.target_ton,
                           target_type=excluded.target_type,
                           daily_target_ton=excluded.daily_target_ton,
                           conversion_target_pct=excluded.conversion_target_pct,
                           active=excluded.active""",
                        (
                            machine, dep,
                            _master_int(row.get("Standard_Manpower"), 0),
                            legacy_shift_target,
                            raw_type,daily_target,conversion_target,
                            _master_bool(row.get("Active"), True)
                        )
                    )

                    # New machines get sensible A/B defaults; explicit SHIFT_STANDARD rows can override them.
                    for _shift in ("A","B"):
                        upsert(
                            """INSERT INTO machine_shift_targets(machine,shift,standard_manpower,target_ton)
                               VALUES (?,?,?,?) ON CONFLICT(machine,shift) DO NOTHING""",
                            (
                                machine,_shift,
                                _master_int(row.get("Standard_Manpower"), 0),
                                legacy_shift_target
                            )
                        )

                elif master_type == "SHIFT_STANDARD":
                    machine_name = _master_text(row.get("Machine"))
                    shift_target = _master_num(row.get("Shift_Target_Ton"), _master_num(row.get("Target_Ton"), 0))
                    if shift_target <= 0:
                        _m = read_df(
                            "SELECT target_type,daily_target_ton FROM machines WHERE machine=? LIMIT 1",
                            (machine_name,)
                        )
                        if not _m.empty and str(_m.iloc[0].get("target_type") or "") == "FIXED_TON":
                            shift_target = float(_m.iloc[0].get("daily_target_ton") or 0) / 2.0
                    upsert(
                        """INSERT INTO machine_shift_targets(machine,shift,standard_manpower,target_ton)
                           VALUES (?,?,?,?)
                           ON CONFLICT(machine,shift) DO UPDATE SET
                           standard_manpower=excluded.standard_manpower,
                           target_ton=excluded.target_ton""",
                        (
                            machine_name,
                            _master_text(row.get("Shift")),
                            _master_int(row.get("Standard_Manpower"), 0),
                            shift_target
                        )
                    )

                elif master_type == "CONTRACTOR":
                    upsert(
                        """INSERT INTO contractors(division,vendor_name,thekedar_name,active)
                           VALUES (?,?,?,?)
                           ON CONFLICT(division,vendor_name,thekedar_name)
                           DO UPDATE SET active=excluded.active""",
                        (
                            _master_text(row.get("Division")),
                            _master_text(row.get("Vendor_Name")),
                            _master_text(row.get("Thekedar_Name")),
                            _master_bool(row.get("Active"), True)
                        )
                    )

                elif master_type == "CONTRACTOR_RATE":
                    con = read_df(
                        """SELECT contractor_id FROM contractors
                           WHERE division=? AND vendor_name=? AND thekedar_name=?
                           LIMIT 1""",
                        (
                            _master_text(row.get("Division")),
                            _master_text(row.get("Vendor_Name")),
                            _master_text(row.get("Thekedar_Name"))
                        )
                    )
                    if con.empty:
                        raise ValueError(
                            "Contractor does not exist. Add CONTRACTOR row before CONTRACTOR_RATE."
                        )
                    contractor_id = int(con.iloc[0]["contractor_id"])
                    effective = _master_text(row.get("Effective_From")) or date.today().isoformat()
                    parsed_effective = pd.to_datetime(effective, errors="coerce")
                    if pd.isna(parsed_effective):
                        raise ValueError("Effective_From must be YYYY-MM-DD or a valid date.")
                    effective = parsed_effective.date().isoformat()
                    upsert(
                        """INSERT INTO contractor_rates(
                           contractor_id,work_type,unit,rate,effective_from,active
                           ) VALUES (?,?,?,?,?,?)""",
                        (
                            contractor_id,
                            _master_text(row.get("Work_Type")),
                            _master_text(row.get("Unit")),
                            _master_num(row.get("Rate"), 0),
                            effective,
                            _master_bool(row.get("Active"), True)
                        )
                    )

                elif master_type == "EMPLOYEE":
                    employee_id = _master_text(row.get("Employee_ID"))
                    join_text = _master_text(row.get("Joining_Date"))
                    joining_date = None
                    if join_text:
                        jd = pd.to_datetime(join_text, errors="coerce")
                        if pd.isna(jd):
                            raise ValueError("Joining_Date must be YYYY-MM-DD or a valid date.")
                        joining_date = jd.date().isoformat()

                    # Employee template updates ONLY identity/employment/contact fields.
                    # Salary/statutory/bank values are maintained by the SALARY template,
                    # so re-uploading Employee Master cannot accidentally zero salary data.
                    upsert(
                        """INSERT INTO employees(
                           employee_id,employee_name,department,designation,employee_type,shift,
                           skill_level,working_days,ot_rate,joining_date,mobile_number,email,status,
                           remarks,division,father_name,salary_active
                           ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                           ON CONFLICT(employee_id) DO UPDATE SET
                           employee_name=excluded.employee_name,
                           department=excluded.department,
                           designation=excluded.designation,
                           employee_type=excluded.employee_type,
                           shift=excluded.shift,
                           skill_level=excluded.skill_level,
                           working_days=excluded.working_days,
                           ot_rate=excluded.ot_rate,
                           joining_date=excluded.joining_date,
                           mobile_number=excluded.mobile_number,
                           email=excluded.email,
                           status=excluded.status,
                           remarks=excluded.remarks,
                           division=excluded.division,
                           father_name=excluded.father_name,
                           salary_active=excluded.salary_active""",
                        (
                            employee_id,
                            _master_text(row.get("Employee_Name")),
                            _master_text(row.get("Department")),
                            _master_text(row.get("Designation")),
                            _master_text(row.get("Employee_Type"), "Permanent") or "Permanent",
                            _master_text(row.get("Default_Shift"), "General") or "General",
                            _master_text(row.get("Skill_Level")),
                            _master_int(row.get("Working_Days"), 26) or 26,
                            _master_num(row.get("OT_Rate"), 0),
                            joining_date,
                            _master_text(row.get("Mobile_Number")),
                            _master_text(row.get("Email")),
                            _master_text(row.get("Employee_Status"), "Active") or "Active",
                            _master_text(row.get("HR_Remarks")),
                            _master_text(row.get("Division")),
                            _master_text(row.get("Father_Husband_Name")),
                            _master_bool(row.get("Payroll_Active"), True),
                        )
                    )

                elif master_type == "SALARY":
                    employee_id = _master_text(row.get("Employee_ID"))
                    salary_div = _normalize_master_division(
                        row.get("Division"), fallback=_master_text(row.get("Division"))
                    )
                    emp = read_df(
                        "SELECT employee_id,division FROM employees WHERE employee_id=? LIMIT 1",
                        (employee_id,)
                    )
                    if emp.empty:
                        raise ValueError(
                            "Employee does not exist. Add EMPLOYEE row before SALARY."
                        )
                    master_div = _clean_text(emp.iloc[0].get("division"))
                    if master_div != salary_div:
                        raise ValueError(
                            f"Division mismatch. Employee Master={master_div}, Salary row={salary_div}."
                        )
                    upsert(
                        """UPDATE employees SET
                           monthly_salary=?,
                           revised_salary_rate=?,
                           increment_amount=?,
                           gross_pay=?,
                           basic_vda=?,
                           hra=?,
                           conveyance=?,
                           other_allowance=?,
                           additional_fixed_allowance=?,
                           pf_applicable=?,
                           esic_applicable=?,
                           uan_number=?,
                           esic_number=?,
                           pan_number=?,
                           bank_name=?,
                           bank_account=?,
                           ifsc_code=?,
                           salary_active=?
                           WHERE employee_id=?""",
                        (
                            _master_num(row.get("Monthly_Salary"), 0),
                            _master_num(row.get("Revised_Salary_Rate"), 0),
                            _master_num(row.get("Increment"), 0),
                            _master_num(row.get("Gross_Pay"), 0),
                            _master_num(row.get("Basic_VDA"), 0),
                            _master_num(row.get("HRA"), 0),
                            _master_num(row.get("Conveyance"), 0),
                            _master_num(row.get("Other_Allowance"), 0),
                            _master_num(row.get("Additional_Fixed_Allowance"), 0),
                            _master_bool(row.get("PF_Applicable"), False),
                            _master_bool(row.get("ESIC_Applicable"), False),
                            _master_text(row.get("UAN_Number")),
                            _master_text(row.get("ESIC_Number")),
                            _master_text(row.get("PAN_Number")),
                            _master_text(row.get("Bank_Name")),
                            _master_text(row.get("Bank_Account")),
                            _master_text(row.get("IFSC")),
                            _master_bool(row.get("Payroll_Active"), True),
                            employee_id
                        )
                    )

                counts[master_type] += 1
            except Exception as exc:
                row_errors.append(f"CSV row {csv_row} ({master_type}): {exc}")

    if row_errors:
        raise ValueError("\\n".join(row_errors[:100]))

    return counts




