def master_specific_template_csv(master_types):
    """Create a clean page-specific CSV without universal helper columns."""
    types = list(master_types if isinstance(master_types, (list, tuple, set)) else [master_types])
    if set(types) == {"MACHINE", "SHIFT_STANDARD"}:
        cols = MASTER_SPECIFIC_COLUMNS["MACHINE_SHIFT"]
    else:
        cols = MASTER_SPECIFIC_COLUMNS.get(types[0], UNIVERSAL_MASTER_COLUMNS)
    return pd.DataFrame(columns=cols).to_csv(index=False).encode("utf-8-sig")


def _prepare_specific_master_df(df, allowed):
    """Convert a simple page template into the universal import schema."""
    if df is None:
        return pd.DataFrame(columns=UNIVERSAL_MASTER_COLUMNS)

    df = df.copy()
    df.columns = [str(c).strip() for c in df.columns]

    # Ignore accidental blank Excel/CSV rows automatically.
    if not df.empty:
        df = df.fillna("")
        nonblank_mask = df.apply(lambda r: any(str(v).strip() for v in r.tolist()), axis=1)
        df = df[nonblank_mask].copy()

    allowed = set(allowed)

    # Expand only inside the application; users do not need the universal columns.
    for col in UNIVERSAL_MASTER_COLUMNS:
        if col not in df.columns:
            df[col] = ""

    # Single-master pages know their own type automatically.
    if len(allowed) == 1:
        df["Master_Type"] = next(iter(allowed))
    else:
        df["Master_Type"] = df["Master_Type"].astype(str).str.strip().str.upper()

    # Row_Action is also automatic on individual pages.
    df["Row_Action"] = df["Row_Action"].astype(str).str.strip()
    df.loc[df["Row_Action"] == "", "Row_Action"] = "UPSERT"

    df = _normalize_master_import_df(df)
    return df[UNIVERSAL_MASTER_COLUMNS]


def render_master_template_tools(title, master_types, file_name, key_prefix):
    """Download and upload the simple template directly on the same master page."""
    allowed = set(master_types if isinstance(master_types, (list, tuple, set)) else [master_types])

    with st.container(border=True):
        t1, t2 = st.columns([1, 1.4])
        with t1:
            st.download_button(
                f"⬇ Download {title} Template",
                data=master_specific_template_csv(allowed),
                file_name=file_name,
                mime="text/csv",
                use_container_width=True,
                key=f"{key_prefix}_download"
            )
            if len(allowed) == 1:
                st.caption("Just fill your data rows. Master_Type and Row_Action are automatic.")
            else:
                st.caption("For this combined page use Master_Type = MACHINE or SHIFT_STANDARD.")

        with t2:
            upload = st.file_uploader(
                f"Upload Filled {title} CSV",
                type=["csv"],
                key=f"{key_prefix}_upload"
            )

        if upload is not None:
            try:
                upload.seek(0)
                raw_df = pd.read_csv(upload, dtype=str, keep_default_na=False)
                raw_df.columns = [str(c).strip() for c in raw_df.columns]
                prepared = _prepare_specific_master_df(raw_df, allowed)

                if prepared.empty:
                    st.warning("No data rows were found in the CSV.")
                else:
                    validation_errors = validate_universal_master_df(prepared)
                    wrong_types = sorted(set(
                        x for x in prepared["Master_Type"].astype(str).str.strip().str.upper().tolist()
                        if x and x not in allowed
                    ))

                    if validation_errors:
                        st.error("Template validation failed.")
                        for err in validation_errors[:30]:
                            st.write("• " + err)
                    elif wrong_types:
                        st.error(
                            f"This page accepts only {', '.join(sorted(allowed))}. "
                            f"Found: {', '.join(wrong_types)}."
                        )
                    else:
                        st.success(f"{len(prepared):,} row(s) ready to import.")
                        preview_cols = [c for c in raw_df.columns if c in prepared.columns]
                        if not preview_cols:
                            preview_cols = ["Master_Type"]
                        st.dataframe(prepared[preview_cols].head(30), hide_index=True, use_container_width=True)

                        confirm = st.checkbox(
                            f"I confirm these {title} rows are correct.",
                            key=f"{key_prefix}_confirm"
                        )
                        if st.button(
                            f"Import / Update {title}",
                            type="primary",
                            use_container_width=True,
                            disabled=not confirm,
                            key=f"{key_prefix}_import"
                        ):
                            counts = import_universal_master_csv(prepared)
                            processed = sum(v for k, v in counts.items() if k in allowed)
                            st.success(f"{processed:,} {title} row(s) processed successfully.")
                            st.rerun()
            except Exception as exc:
                st.error(f"{title} CSV import failed: {exc}")



