def render_business_rules_template_tools():
    editable = {
        "pf_employee_rate_pct","pf_wage_ceiling","esic_employee_rate_pct",
        "half_day_cost_factor","waste_warning_pct","waste_critical_pct",
        "breakdown_warning_hours","breakdown_critical_hours"
    }
    with st.container(border=True):
        c1, c2 = st.columns([1, 1.4])
        with c1:
            st.download_button(
                "⬇ Download Business Rules Template",
                data=business_rules_template_csv(),
                file_name="Reliable_Packaging_Business_Rules_Template.csv",
                mime="text/csv",
                use_container_width=True,
                key="v64_rules_download"
            )
        with c2:
            upload = st.file_uploader(
                "Upload Filled Business Rules CSV",
                type=["csv"],
                key="v64_rules_upload"
            )
        if upload is not None:
            try:
                upload.seek(0)
                df = pd.read_csv(upload, dtype=str, keep_default_na=False)
                required = {"Setting_Key","Setting_Value"}
                if not required.issubset(df.columns):
                    st.error("Required columns: Setting_Key, Setting_Value")
                else:
                    invalid = sorted(set(df["Setting_Key"].astype(str).str.strip()) - editable)
                    if invalid:
                        st.error("Unsupported/locked setting(s): " + ", ".join(invalid))
                    else:
                        st.dataframe(df, hide_index=True, use_container_width=True)
                        confirm = st.checkbox(
                            "I confirm these business-rule values are correct.",
                            key="v64_rules_confirm"
                        )
                        if st.button(
                            "Import / Update Business Rules",
                            type="primary",
                            use_container_width=True,
                            disabled=not confirm,
                            key="v64_rules_import"
                        ):
                            for _, r in df.iterrows():
                                save_setting_value(str(r["Setting_Key"]).strip(), str(r["Setting_Value"]).strip())
                            # Locked policies remain locked regardless of CSV.
                            save_setting_value("salary_basis", "calendar_days")
                            save_setting_value("ot_threshold_hours", 12.0)
                            save_setting_value("ot_multiplier", 1.0)
                            save_setting_value("ap_pa_treatment", "HR Review")
                            st.success("Business rules updated. Locked payroll policies remain unchanged.")
                            st.rerun()
            except Exception as exc:
                st.error(f"Business Rules CSV import failed: {exc}")


def v5_month_options(n_back=18, n_forward=3):
    today = date.today()
    current = date(today.year, today.month, 1)
    options=[]
    for offset in range(-n_back, n_forward+1):
        y = current.year + (current.month - 1 + offset)//12
        m = (current.month - 1 + offset)%12 + 1
        options.append(date(y,m,1))
    return sorted(set(options), reverse=True)


