                    attendance_bonus=c2.number_input("Attendance Bonus",min_value=0.0,value=float(ex.get("attendance_bonus") or 0),step=100.0)
                    endorsement_allowance=c3.number_input("Endorsement Allowance",min_value=0.0,value=float(ex.get("endorsement_allowance") or 0),step=100.0)
