                    pf_override=c3.number_input("PF Override (0 = calculated)",min_value=0.0,value=float(ex.get("pf_override") or 0),step=50.0)
                    esic_override=st.number_input("ESIC Override (0 = calculated)",min_value=0.0,value=float(ex.get("esic_override") or 0),step=10.0)
                    remark=st.text_area("HR Payroll Remark",value=str(ex.get("remark") or ""),height=65)
